let mcpAudit=[];
function initWorkflowState(){Object.assign(state,{mode:'model',ribbon:'architecture',selected:null,selection:[],plane:'XY · Ground floor',planeSource:'Origin / datum',sketchReferences:[],edgeStyle:'Fillet',edgeSize:3,measurePicks:[],measureSlot:0,measureType:'Faces',wallDraft:[],customWalls:[],buildingPlacements:[],typeIndex:0,typeName:'Interior stud · 100',typeThickness:100,typeMaterial:'Gypsum / timber stud',typeHeight:2800,doorWidth:900,doorHeight:2100,windowSill:900,stairRisers:16,stairGoing:270,stairWidth:1000,stairHeight:2800,connectionStyle:'Miter',connectionAngle:90,railPitch:32,railLinked:false,guideHeight:2800,guideKind:'Floor plan',guides:[],partTags:{},activeSheet:0,sheetSelected:false,viewSelected:false,activeExportSet:0,exportSetSelected:false,exposedOnly:false,renderStyle:'Shaded edges',renderBackground:'Warm studio',mcpTab:'pending',mcpPending:null,parameters:[{name:'cabinet_width',description:'Outside width of the cabinet',value:'600',unit:'mm',exposed:true},{name:'stock_thickness',description:'Finished panel stock thickness',value:'18',unit:'mm',exposed:true},{name:'rail_gap',description:'Space reserved for each drawer rail',value:'12.7',unit:'mm',exposed:false},{name:'drawer_width',description:'Clear drawer width between rails',value:'cabinet_width - 2 * stock_thickness - 2 * rail_gap',unit:'mm',exposed:false}],buildingTypes:[{kind:'wall',name:'Interior stud · 100',thickness:100,material:'Gypsum / timber stud',height:2800},{kind:'wall',name:'Exterior masonry · 240',thickness:240,material:'Masonry / plaster',height:2800},{kind:'door',name:'Internal door · 900',thickness:40,material:'Oak',width:900,height:2100},{kind:'window',name:'Double window · 1200',thickness:100,material:'Glass / timber',width:1200,height:1200},{kind:'level',name:'Raised platform · 200',thickness:200,material:'Birch plywood',height:200},{kind:'stairs',name:'Straight timber stair',thickness:40,material:'Oak',height:2800}],sheets:[{number:'A-001',name:'Ground floor / fabrication',paper:'A3 landscape',scale:'1:5',author:'Tobias Keller',project:projects[state.project].name,revision:'A',views:['Front','Right','Section A–A','Isometric'],note:state.drawingNote},{number:'A-002',name:'Sections & details',paper:'A3 landscape',scale:'1:2',author:'Tobias Keller',project:projects[state.project].name,revision:'A',views:['Section B–B','Detail C'],note:'Verify all mating dimensions.'}],exportSets:[{name:'CNC wood parts',tags:['wood','cnc'],match:'All tags',formats:['DXF','CSV','PDF'],aids:false},{name:'Metal fabrication',tags:['metal'],match:'Any tag',formats:['STEP','DXF','PDF'],aids:false},{name:'Printed parts',tags:['print'],match:'Any tag',formats:['3MF'],aids:true},{name:'Site drawing package',tags:['site'],match:'Any tag',formats:['PDF','DXF'],aids:false}],materialStyles:{'Birch plywood':{hatch:'Wood grain',angle:45,spacing:4},'Steel · S235':{hatch:'Cross hatch',angle:45,spacing:3},'Aluminium · 5052':{hatch:'Diagonal',angle:45,spacing:4},PETG:{hatch:'Diagonal',angle:30,spacing:6},Glass:{hatch:'Diagonal',angle:60,spacing:8}}});
 projects.tower={name:'Building section study',sub:'Architecture · Drawing guides',workspace:'room',selected:'Floor 03',parts:['Core','Floor 01','Floor 02','Floor 03','Facade'],materials:['Concrete','Concrete','Concrete','Concrete','Glass'],version:'03',file:'building-study',subtitle:'8 levels · 3,000 mm floor-to-floor'};
}
function defaultTags(name,material){return material?.includes('Birch')||material==='Oak'?['wood','cnc']:material==='PETG'?['print']:material?.includes('Steel')||material?.includes('Aluminium')?['metal']:['site'];}
function tagsFor(name){const key=state.project+':'+name;return state.partTags[key]||defaultTags(name,projects[state.project].materials[projects[state.project].parts.indexOf(name)]);}
function syncWorkflowContext(){const w=state.workspace;state.mode=w==='sketch'?'sketch':w==='drawings'?'drawings':'model';state.ribbon=w==='room'?'architecture':['wood','sheet','weld','assembly','print'].includes(w)?w:'common';}
function switchMode(id){state.mode=id;state.ribbon='common';state.operation=null;state.measure=false;state.modal=null;state.inspector='properties';state.manufacturing=null;state.sheetSelected=false;state.viewSelected=false;state.exportSetSelected=false;if(id==='sketch'){state.workspace='sketch';state.view='sketch';state.selected='Master sketch';state.selection=[];}if(id==='model'){state.workspace=projects[state.project].workspace==='drawings'?'model':projects[state.project].workspace;state.ribbon=state.workspace==='room'?'architecture':['wood','sheet','weld','assembly','print'].includes(state.workspace)?state.workspace:'common';state.view=state.workspace==='room'?'plan':'3d';}if(id==='drawings'){state.selection=[];state.workspace='drawings';state.view='sheet';state.selected=null;state.sheetSelected=true;}if(id==='render'){state.workspace='model';state.view='3d';state.selected=null;state.operation={kind:'render-style',label:'Viewport appearance'};}if(id==='parameters'||id==='export'){state.selected=null;state.selection=[];}render();}
function switchRibbon(id){state.ribbon=id;state.operation=null;state.manufacturing=null;if(state.mode==='model'){state.workspace=id==='architecture'?'room':['wood','sheet','weld','assembly','print'].includes(id)?id:'model';state.view=id==='architecture'&&state.project==='makerspace'?'plan':'3d';state.flat=false;}render();}
function renderApplication(){const p=projects[state.project],color=modes.find(m=>m[0]===state.mode)?.[3]||'#4e806c';app.innerHTML=`<main class="app revision-two" style="--mode-color:${color}" data-stage="${state.mode}" aria-label="MultiCAD desktop prototype">
<header class="topbar"><div class="brand"><span class="brand-mark"><span></span></span>MULTICAD</div><span class="rule"></span><button class="project-button" data-action="projects">${p.name}${icon('down')}</button><span class="pill save-state ${state.saved?'':'orange'}">${state.saved?'Saved':'Unsaved'}</span><div class="row file-actions"><button class="icon-btn" data-action="save" aria-label="Save project" title="Save · ⌘S">${icon('save')}</button><button class="icon-btn" data-action="undo" aria-label="Undo" ${undoStack.length?'':'disabled'}>${icon('undo')}</button><button class="icon-btn" data-action="redo" aria-label="Redo" ${redoStack.length?'':'disabled'}>${icon('redo')}</button></div><button class="top-search" data-action="commands">${icon('search')}<span>Find a tool</span><span class="key">⌘ K</span></button><nav class="mode-tabs" aria-label="Application mode">${modes.map(([id,i,label,c])=>`<button data-mode="${id}" style="--tab-color:${c}" class="mode-tab ${state.mode===id?'active':''}" aria-current="${state.mode===id?'page':'false'}">${icon(i)}${label}</button>`).join('')}</nav><button class="avatar" data-action="settings" aria-label="User and application settings">TK</button></header>
<div class="ribbon-row"><nav class="ribbon-tabs" aria-label="Ribbon workspace">${ribbonTabs[state.mode].map(([id,label])=>`<button data-ribbon="${id}" class="${state.ribbon===id?'active':''}">${label}</button>`).join('')}</nav><div class="global-tools"><button data-action="measure" class="${state.measure?'active':''}">${icon('ruler')}Measure</button><button data-action="library">${icon('library')}Library</button><button data-action="mcp" class="mcp-global">${icon('branch')}MCP${state.mcpPending?'<span class="pending-dot"></span>':''}</button></div></div>
<div class="toolbar ribbon-tools" aria-label="${state.mode} ${state.ribbon} tools">${(ribbonTools[state.mode+':'+state.ribbon]||[]).map(([i,l,a])=>`<button class="ribbon-tool ${state.operation?.kind===a?'active':''}" data-action="${a}">${icon(i)}<span>${l}</span></button>`).join('')}<span class="spacer"></span><span class="ribbon-caption">${state.mode==='parameters'?'One source of dimensions':state.mode==='export'?'Saved, repeatable deliverables':'Shared project · Contextual tools'}</span></div>
<div class="main">${projectTree()}${centerWorkspace()}${workflowInspector()}</div><footer class="statusbar"><button data-action="health">${icon(state.sketchIssue?'alert':'check')}${state.sketchIssue?'Reference needs attention':'Model up to date'}</button><span>mm</span><span>${state.selection.length||Number(!!state.selected)} selected</span><span class="spacer"></span><span class="prototype-tag">UX PROTOTYPE · SIMULATED GEOMETRY & OUTPUTS</span><button data-action="mcp">${icon('branch')}${state.mcpPending?'1 pending MCP transaction':'MCP activity'}</button><button data-action="tour">${icon('help')}Explore workflows</button></footer></main>`;renderModal();bindCanvas();}
function projectTree(){const p=projects[state.project],parts=[...p.parts,...state.placed];return `<aside class="tree-panel" aria-label="Parts and assemblies"><div class="panel-heading"><strong>Parts & assemblies</strong><button class="icon-btn" data-action="new-part" aria-label="Add part">${icon('plus')}</button></div><label class="tree-search">${icon('search')}<input placeholder="Filter parts" data-tree-search aria-label="Filter project objects"></label><div class="tree-root">${icon('down')}${icon('folder')}${p.name}</div><div class="tree-group">${parts.map(name=>`<div class="part-row ${state.selection.includes(name)||state.selected===name?'selected':''} ${state.hidden.includes(name)?'faded':''}"><input type="checkbox" data-multi-part="${esc(name)}" aria-label="Select ${esc(name)}" ${state.selection.includes(name)?'checked':''}><button class="tree-item" data-part="${esc(name)}">${icon(/frame|hinge|carcass|rail/i.test(name)?'assembly':'cube')}<span>${esc(name)}</span></button><button class="eye" data-eye="${esc(name)}" aria-label="Visibility of ${esc(name)}">${icon(state.hidden.includes(name)?'hide':'eye')}</button></div>`).join('')}</div><div class="tree-group"><div class="tree-group-label">Reference geometry</div><button class="tree-item" data-action="open-sketch">${icon('sketch')}Master sketch<span class="mini-count">↗ 3</span></button><button class="tree-item" data-action="choose-plane">${icon('plane')}Planes & external references</button>${state.project==='case'?`<button class="tree-item" data-action="rail-example">${icon('link')}Rail → carcass hole transfer</button>`:''}${state.project==='console'?`<button class="tree-item" data-action="pcb">${icon('link')}control-board.kicad_pcb</button>`:''}</div><div class="tree-group"><div class="tree-group-label">Drawing definitions</div><button class="tree-item" data-mode="drawings">${icon('drawing')}Drawing pages<span class="mini-count">${state.sheets.length}</span></button><button class="tree-item" data-action="floor-guide">${icon('plane')}3D drawing guides<span class="mini-count">${state.guides.length}</span></button><button class="tree-item" data-mode="export">${icon('download')}Export sets<span class="mini-count">${state.exportSets.length}</span></button></div><div class="tree-bottom"><div class="eyebrow">Reusable by design</div><p>A part or assembly can become a symbol with exposed parameters.</p>${button('create-symbol','Create symbol','library','small')}</div><div class="tree-status">${icon('file')}Local project · Rev ${p.version}</div></aside>`;}
function centerWorkspace(){if(state.mode==='parameters')return `<section class="center board-center" aria-label="Design canvas"><div id="scene" class="board-scroll">${parametersBoard()}</div></section>`;if(state.mode==='export')return `<section class="center board-center" aria-label="Design canvas"><div id="scene" class="board-scroll">${exportsBoard()}</div></section>`;
return `<section class="center" aria-label="Design canvas"><div class="viewport ${state.grid?'':'no-grid'} ${state.mode==='render'?'render-preview':''}" data-display="${esc(state.renderStyle)}" data-background="${esc(state.renderBackground)}"><div class="view-head"><div><div class="canvas-breadcrumb">${state.mode==='sketch'?esc(state.plane):state.mode==='drawings'?activeSheet().number:esc(projects[state.project].name)} <span>/</span> ${ribbonTabs[state.mode].find(r=>r[0]===state.ribbon)?.[1]||'Common'}</div><h1 class="view-title">${state.mode==='drawings'?esc(activeSheet().name):viewTitle()}</h1><div class="view-sub">${state.mode==='sketch'?'Sketch always has a plane · Project or intersect external geometry':state.mode==='drawings'?`${activeSheet().paper} · ${activeSheet().scale} · ${activeSheet().views.length} views`:viewSub()}</div></div><div class="view-mode">${(state.mode==='drawings'?['Sheet','Model']:state.mode==='sketch'?['Sketch','3D']:['Plan','3D']).map(v=>`<button data-view="${v.toLowerCase()}" class="${isView(v)?'active':''}">${v}</button>`).join('')}</div></div><div class="scene" id="scene">${scene()}</div>${state.mode==='sketch'?`<button class="plane-badge" data-action="choose-plane">${icon('plane')}${esc(state.plane)}</button>`:''}<div class="view-tools">${[['zoom-in','plus','Zoom in'],['zoom-out','minus','Zoom out'],['fit-view','fit','Fit view'],['toggle-grid','grid','Toggle grid'],['section','section','Section view']].map(([a,i,l])=>`<button class="icon-btn" data-action="${a}" aria-label="${l}">${icon(i)}</button>`).join('')}</div><div class="scene-hint">${state.measure?'Select reference A, then reference B · Faces, edges, or points':state.operation?.kind==='wall'?'Click a start point and an end point on the floor plane':state.mode==='sketch'?'Select profiles · Project coplanar geometry or intersect a crossing object':state.mode==='drawings'?'Views are linked to the model · Material controls section hatching':'Drag empty canvas to orbit · Click to select · Esc clears selection'}</div>${state.operation?`<div class="operation-preview">${icon(state.operation.fromMcp?'branch':'eye')}<div><strong>${state.operation.fromMcp?'MCP preview':'Preview'} · ${esc(state.operation.label)}</strong><small>${state.operation.fromMcp?'External client · One undoable transaction':'Review in the inspector, then apply'}</small></div></div>`:state.selected?`<div class="selection-chip">${icon('cube')}${esc(state.selected)}<button data-action="clear-selection" aria-label="Clear selection">${icon('close')}</button></div>`:''}${state.manufacturing?manufacturing():''}</div>${state.mode==='drawings'?sheetStrip():timeline()}</section>`;}
function activeSheet(){return state.sheets[state.activeSheet]||state.sheets[0];}
function sheetStrip(){return `<div class="sheet-strip" aria-label="Drawing pages">${state.sheets.map((s,i)=>`<button data-sheet="${i}" class="${state.activeSheet===i?'active':''}">${icon('drawing')}<span><strong>${s.number}</strong><small>${esc(s.name)}</small></span><span class="mini-count">${s.views.length}</span></button>`).join('')}<button data-action="add-page" class="add-sheet">${icon('plus')}Add page</button></div>`;}
function parametersBoard(){const rows=state.parameters.map((p,i)=>({p,i})).filter(({p})=>!state.exposedOnly||p.exposed);return `<div class="board-heading"><div><span class="eyebrow">Project definition</span><h1>Parameters</h1><p>Name the dimensions that drive the design. Exposed values become inputs when you reuse it as a symbol.</p></div>${button('add-parameter','Add parameter','plus','primary')}</div><div class="parameter-summary"><span>${state.parameters.length} parameters</span><span>${state.parameters.filter(p=>p.exposed).length} exposed</span><span>${icon('link')}Units stay explicit</span></div><div class="parameter-table-wrap"><table class="parameter-table"><thead><tr><th>Name</th><th>Description</th><th>Value / expression</th><th>Unit</th><th>Expose</th><th></th></tr></thead><tbody>${rows.map(({p,i})=>`<tr><td><input aria-label="Parameter ${i+1} name" data-param="${i}:name" value="${esc(p.name)}" placeholder="parameter_name"></td><td><input aria-label="Parameter ${i+1} description" data-param="${i}:description" value="${esc(p.description)}" placeholder="What does this control?"></td><td><input class="mono" aria-label="Parameter ${i+1} value" data-param="${i}:value" value="${esc(p.value)}"><small>${parameterResult(p)}</small></td><td><select aria-label="Parameter ${i+1} unit" data-param="${i}:unit">${['mm','°','count','ratio'].map(u=>`<option ${u===p.unit?'selected':''}>${u}</option>`).join('')}</select></td><td class="expose-cell"><input type="checkbox" aria-label="Expose ${esc(p.name||'new parameter')}" data-param="${i}:exposed" ${p.exposed?'checked':''}></td><td><button class="icon-btn" data-delete-param="${i}" aria-label="Delete parameter ${esc(p.name)}">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div><div class="parameter-footnote">${icon('library')}The definition keeps its internal parameters. Each dynamic instance asks only for the exposed ones.</div><div class="board-note"><strong>Example dependency</strong><span class="mono">cabinet_width → drawer_width → drawer panels → hole positions → drawings & cut list</span></div>`;}
function parameterResult(p){if(/^-?\d+(\.\d+)?$/.test(p.value.trim()))return 'Driving value';if(p.name==='drawer_width'){const get=n=>Number(state.parameters.find(x=>x.name===n)?.value||0);return `= ${(get('cabinet_width')-2*get('stock_thickness')-2*get('rail_gap')).toFixed(1)} mm · Derived`;}return 'Expression · Preview only';}
function matchedParts(set){return [...projects[state.project].parts,...state.placed].filter(name=>{const tags=tagsFor(name);return !set.tags.length|| (set.match==='All tags'?set.tags.every(t=>tags.includes(t)):set.tags.some(t=>tags.includes(t)));});}
function exportsBoard(){const set=state.exportSets[state.activeExportSet],parts=matchedParts(set);return `<div class="board-heading"><div><span class="eyebrow">Repeatable deliverables</span><h1>Export sets</h1><p>Save what to include and how to deliver it. Tags keep the set current as parts are added or changed.</p></div>${button('new-export-set','New set','plus','primary')}</div><div class="export-workbench"><div class="export-set-list">${state.exportSets.map((s,i)=>`<button data-export-set="${i}" class="set-card ${i===state.activeExportSet?'active':''}"><span class="set-card-title">${icon(s.formats.includes('3MF')?'print':'folder')}<strong>${esc(s.name)}</strong></span><span>${s.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</span><small>${s.formats.join(' · ')} <span>${matchedParts(s).length} parts</span></small></button>`).join('')}</div><div class="export-set-detail"><div class="row spread"><div><h2>${esc(set.name)}</h2><span class="muted">${set.match==='All tags'?'Match all':'Match any'}: ${set.tags.map(t=>'<b>'+esc(t)+'</b>').join(' + ')||'All parts'}</span></div><button class="icon-btn" data-action="edit-export-set" aria-label="Edit export set">${icon('settings')}</button></div><div class="section-label">Resolved parts <span>${parts.length} matches</span></div>${parts.length?parts.map(name=>`<button class="resolved-part" data-part="${esc(name)}">${icon('cube')}<span>${esc(name)}</span><span class="spacer"></span>${tagsFor(name).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</button>`).join(''):`<div class="empty-result">${icon('search')}<strong>No parts match these tags</strong><p>Select a part on the left to edit its tags, or choose a different set.</p></div>`}<div class="section-label">Output recipes</div>${set.formats.map(f=>`<div class="recipe-row"><span class="output-icon">${f}</span><div><strong>${{DXF:'Part contours / flat patterns',PDF:'Linked drawing pages',CSV:'Parts and cut list',STEP:'Solid geometry',GLB:'Blender scene',OBJ:'Mesh objects','3MF':'Print parts and design aids',STL:'Print meshes'}[f]}</strong><small>${f==='DXF'?'1:1 · CUT / BEND / DRILL layers':f==='PDF'?state.sheets.length+' pages · page sizes and title blocks':f==='3MF'?(set.aids?'Include removable design aids':'Exclude removable aids'):'Names, units, and placements retained'}</small></div></div>`).join('')}<div class="export-ready">${icon(parts.length?'check':'info')}<span>${parts.length?'Ready for package preview':'Assign matching tags to preview a package'}</span>${button('preview-set','Preview package','arrow','primary',parts.length?'':'disabled')}</div></div></div>`;}
function workflowInspector(){const empty=!state.selected&&!state.operation&&!state.measure&&!state.sheetSelected&&!state.exportSetSelected;let content='',actions='';if(state.measure){content=measureInspector();actions=button('close-measure','Done','check','primary')+button('measure-reset','Clear references','','small');}else if(state.operation){content=toolInspector();actions=button('cancel-op','Cancel')+button(state.operation.fromMcp?'mcp-apply':'apply-op',state.operation.fromMcp?'Apply transaction':'Apply','check','primary');}else if(state.sheetSelected){content=sheetInspector();actions=button('page-setup','Page setup','settings','small')+button('export','Export pages','download','primary');}else if(state.exportSetSelected){content=exportSetInspector();actions=button('edit-export-set','Edit set','settings','small')+button('preview-set','Preview','eye','primary');}else if(state.selected){content=partInspector();actions=button('copy-part','Copy','file','small')+button('move','Move','move','small')+button('create-symbol','Symbol','library','small');}
return `<aside class="inspector ${empty?'empty-inspector':''}" aria-label="Inspector"><div class="inspector-heading"><strong>Inspector</strong>${!empty?`<button class="icon-btn small-ico" data-action="clear-selection" aria-label="Clear inspector">${icon('close')}</button>`:''}</div>${empty?'<div class="inspector-blank"></div>':`<div class="inspector-content">${content}</div><div class="inspector-actions">${actions}</div>`}</aside>`;}
function selectedMaterial(){const p=projects[state.project];return state.materialAssignments?.[state.project+':'+state.selected]||p.materials[p.parts.indexOf(state.selected)]||p.materials[0]||'Birch plywood';}
function partInspector(){const mat=selectedMaterial(),count=state.selection.length;return `<div class="object-type">${icon(count>1?'layers':'cube')}${count>1?'Multiple parts · '+count:'Part / assembly'}</div><h2 class="object-name">${count>1?count+' selected parts':esc(state.selected)}</h2><div class="section-label">Material</div><button class="material material-button" data-action="assign-material"><span class="swatch ${mat.includes('Birch')?'':'metal-swatch'}"></span><span>${esc(mat)}<small>Stock, appearance & drawing hatch</small></span>${icon('chevron')}</button><div class="section-label">Tags</div><div class="tags-row">${tagsFor(state.selected).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><input class="full-input tag-input" aria-label="Part tags" data-part-tags value="${esc(tagsFor(state.selected).join(', '))}" placeholder="wood, cnc, batch-a"><small class="field-help">Comma-separated labels · Used by export sets</small><div class="section-label">Properties</div>${state.workspace==='wood'?field('Panel thickness',state.woodThickness,'woodThickness')+selectField('Grain','grain',['Along length','Along width'],state.grain||'Along length'):state.workspace==='sheet'?field('Thickness',state.sheetThickness,'sheetThickness')+field('Inside radius',state.bendRadius,'bendRadius'):field('Height / depth',state.depth,'depth')}${button('drawing-material','Drawing hatch style','section','small')}<div class="section-label">Relationships</div><button class="list-action" data-action="show-dependencies">${icon('link')}Sources & dependents${icon('chevron')}</button>${state.project==='case'?`<button class="list-action" data-action="rail-example">${icon('hole')}Project rail holes into panels${icon('chevron')}</button>`:''}<div class="section-label">Quick actions</div><button class="list-action" data-action="new-sketch">${icon('sketch')}Sketch on selected face${icon('chevron')}</button><button class="list-action" data-action="appearance">${icon('eye')}Rendering properties${icon('chevron')}</button>`;}
function operationHeader(op,text=''){return `<div class="object-type">${icon(op.fromMcp?'branch':op.icon||'sliders')}${op.fromMcp?'MCP · External client':state.mode+' / '+state.ribbon}</div><h2 class="object-name">${esc(op.label)}</h2>${text?`<p class="inspector-description">${text}</p>`:''}`;}
function toolInspector(){const op=state.operation;let h=operationHeader(op);if(['wall','door','window','level','stairs'].includes(op.kind))return buildingToolInspector(op);
if(op.kind==='measure')return measureInspector();if(op.kind==='motion-controls')return legacyProperties();if(op.kind==='drawing-view')return h+selectField('Scale','selectedViewScale',['1:1','1:2','1:5','1:10','1:50'],state.viewScales?.[activeSheet().number+':'+op.viewIndex]||activeSheet().scale)+check('viewHatch','Use material section hatches',true)+check('viewDims','Associative dimensions',true)+button('page-setup','Page & title block','settings','small');if(op.kind==='profile'||op.kind==='frame-path')return h+selectField('Path source','framePath',['Selected sketch segments','Selected edges','3D polyline'],'Selected sketch segments')+selectField('Stock profile','stockProfile',['SHS 30 × 30 × 2','RHS 40 × 20 × 2','CHS Ø 32 × 2','Angle 30 × 30 × 3'],'SHS 30 × 30 × 2')+selectField('Material','stockMaterial',['Steel · S235','Stainless · 304','Aluminium'],'Steel · S235')+selectField('Alignment','profileAlignment',['Centerline','Outside corner','Selected datum'],'Centerline')+check('memberIds','One stock member per path segment',true)+notice('Connections trim the member ends. Cut lists retain stock profile, length, end angles, and orientation.','','weld')+button('member-connection','Connect member ends','joint','small');
if(op.kind==='sketch-references')return h+`<p class="inspector-description">Project geometry that lies on this plane, or intersect objects that cross it. Resulting sketch references keep their source identities.</p><div class="target-box">${icon('plane')}${esc(state.plane)}</div><div class="section-label">Reference method</div>${selectField('Method','referenceMethod',['Auto · Project / intersect','Project coplanar edges','Intersect with plane'],state.referenceMethod||'Auto · Project / intersect')}<div class="reference-option"><strong>Same plane</strong><span>Neighboring cabinet front → matching edge</span>${button('reference-coplanar','Use cabinet edge','link','small')}</div><div class="reference-option"><strong>Crosses the plane</strong><span>Wall → intersection point / line</span>${button('reference-intersection','Use wall intersection','section','small')}</div><div class="section-label">Selected references</div>${state.sketchReferences.map(r=>`<div class="target-box">${icon('link')}${esc(r)}</div>`).join('')||'<p class="muted">Select a source in the canvas.</p>'}${check('liveReferences','Keep associative reference',true)}`;
if(op.kind==='edge-treatment')return h+`<p class="inspector-description">One edge treatment. Switch the profile without starting a different tool.</p><div class="segmented">${['Fillet','Chamfer'].map(s=>`<button data-edge-style="${s}" class="${state.edgeStyle===s?'active':''}">${s}</button>`).join('')}</div><div class="section-label">Edges</div><div class="target-box">${icon('line')}${esc(state.selected||'Select model geometry')} · Edge chain</div>${field(state.edgeStyle==='Fillet'?'Radius':'Distance',state.edgeSize,'edgeSize')}${state.edgeStyle==='Chamfer'?field('Angle',45,'chamferAngle','°'):selectField('Continuity','edgeContinuity',['Circular','Curvature continuous'],'Circular')}${check('tangentChain','Include tangent chain',true)}${button('toggle-edge-style','Switch profile','refresh','small')}`;
if(op.kind==='holes')return railTransferInspector(op);
if(op.kind==='joint')return h+`<p class="inspector-description">Select mating edges or faces on multiple panels. One joint feature owns the cuts in all targets.</p><div class="section-label">Participating panels</div>${(state.selection.length>1?state.selection:['Laminated top','Angled side panel']).map(p=>`<div class="target-box">${icon('wood')}${esc(p)}</div>`).join('')}${check('jointBatch','Repeat on matching panel pairs',state.selection.length>2)}<div class="section-label">Joint arrangement</div><div class="option-grid">${[['finger','Finger'],['miter','Miter'],['butt-a','Butt · A through'],['butt-b','Butt · B through']].map(([id,n])=>`<button data-joint="${id}" class="${id===state.joint?'active':''}">${icon('joint')}${n}</button>`).join('')}</div>${state.joint==='finger'?field('Finger count',state.fingers,'fingers','')+field('Fit allowance',.15,'jointClearance'):state.joint==='miter'?field('Mating angle',45,'miterAngle','°'):field('Overlap',state.woodThickness,'overlap')}${check('jointBoth','Cut all receiving panels',true)}${notice('A thickness change rebuilds both mating sides and their cut-list dimensions.','','link')}`;
if(op.kind==='panel-edges')return h+selectField('Grain direction','grain',['Along length','Along width','Selected edge'],state.grain||'Along length')+check('grainLocked','Keep grain direction in cut list',true)+'<div class="section-label">Edge treatment</div>'+['Front','Back','Left','Right'].map(edge=>check('edge-'+edge,edge+' edge band',edge==='Front')).join('')+field('Band thickness',1,'bandThickness')+selectField('Sizing','edgeSizing',['Finished outside size','Core panel size'],'Finished outside size')+field('Machining allowance',.5,'machiningAllowance')+notice('Core cut size accounts for edge banding. Finished dimensions and grain are recorded separately.','','wood');
if(op.kind==='panel'||op.kind==='carcass')return h+`<p class="inspector-description">${op.kind==='panel'?'Create stock-based panels from a sketch region or two boundaries.':'Define the outside envelope, then choose which panels and partitions it contains.'}</p>${selectField('Source','panelSource',['Sketch region','Between selected boundaries','Sized panel'],'Sketch region')}${field('Outside width',state.libraryWidth,'libraryWidth')}${field('Depth',state.libraryDepth,'libraryDepth')}${op.kind==='carcass'?field('Height',state.libraryHeight,'libraryHeight'):''}${selectField('Stock','panelStock',['Birch plywood · 18 mm','Birch plywood · 12 mm','MDF · 19 mm'],'Birch plywood · 18 mm')}${field('Finished thickness',state.woodThickness,'woodThickness')}${op.kind==='carcass'?check('boxSides','Left / right sides',true)+check('boxEnds','Top / bottom',true)+check('boxBack','Recessed back',true)+field('Adjustable shelves',2,'shelfCount',''):''}${selectField('Grain','grain',['Along length','Along width'],'Along length')}${notice('Stock thickness drives joints. Part identities and grain stay in the cut list.','','wood')}`;
if(op.kind==='laminate')return h+`<p class="inspector-description">Place existing panels face-to-face and keep them related. This is a stack of parts, not a special material type.</p><div class="target-box">${icon('layers')}Top · Layer 1 → Top · Layer 2</div>${selectField('Alignment','stackAlignment',['Flush outside edges','Selected datum faces','Centered'],'Flush outside edges')}${field('Glue gap',.1,'glueGap')}${check('keepLayers','Keep layers as separate cut-list parts',true)}${check('stackAssembly','Group as a finished panel assembly',true)}${notice('Each layer retains its material, thickness, and grain. The finished stack reports total thickness.','','link')}`;
if(['groove','panel-drill'].includes(op.kind))return h+`${selectField('Operation','panelMachining',op.kind==='groove'?['Dado / groove','Rabbet / rebate','Back panel recess']:['Through drill','Blind drill','Pocket','Dowel / cam pattern'],op.kind==='groove'?'Dado / groove':'Blind drill')}<div class="section-label">Receiving panels</div>${(state.selection.length?state.selection:['Plywood carcass']).map(p=>check('machining-'+p,esc(p),true)).join('')}${field('Diameter / width',8,'pocketWidth')}${field('Depth',12,'pocketDepth')}${field('Edge distance',32,'edgeDistance')}${check('panelLinked','Derive pattern from hardware or mating part',true)}${button('rail-example','Try rail hole transfer','hole','small')}`;
if(['member-connection','cope','weld-joint'].includes(op.kind))return memberConnectionInspector(op);
if(['base-sheet','bend','sheet-corner','hem','cutout'].includes(op.kind))return sheetToolInspector(op);
if(['floor-guide','section-guide','elevation-guide','repeat-guides'].includes(op.kind))return guideInspector(op);
if(op.kind==='dependencies')return relationshipsInspector()+`<div class="section-label">Worked example</div>${button('rail-example','Rail holes → wood panel','hole','primary')}`;
if(op.kind==='render-style'||op.kind==='render-camera')return h+`${selectField('Style','renderStyle',['Shaded edges','Solid','Wireframe','X-ray'],state.renderStyle)}${selectField('Background','renderBackground',['Warm studio','White','Graphite'],state.renderBackground)}${selectField('Camera','renderCamera',['Current isometric','Front','Top','Saved perspective'],state.renderCamera||'Current isometric')}${check('renderShadows','Basic ground shadow',true)}${notice('Lightweight viewport preview. Use GLB for final materials and lighting in Blender.','','eye')}${button('blender-export','Blender handoff','download','small')}`;
if(op.fromMcp)return mcpInspector();
return legacyOperationInspector();}
function buildingToolInspector(op){const kinds={wall:'wall',door:'door',window:'window',level:'level',stairs:'stairs'},kind=kinds[op.kind],types=state.buildingTypes.map((t,i)=>({...t,i})).filter(t=>t.kind===kind);return operationHeader(op,kind==='wall'?'Draw connected segments using a reusable wall type. Type changes can update its instances.':'Place an instance of a saved type, then adjust its dimensions if needed.')+`<div class="section-label">Saved ${kind} type</div><select class="full-input" aria-label="Building type" data-building-type>${types.map(t=>`<option value="${t.i}" ${t.i===state.typeIndex?'selected':''}>${esc(t.name)}</option>`).join('')}</select><div class="section-label">Type definition</div><label class="input-label">Name<input class="full-input" data-text="typeName" value="${esc(state.typeName)}" aria-label="Type name"></label>${kind==='wall'?field('Thickness',state.typeThickness,'typeThickness')+field('Height',state.typeHeight,'typeHeight'):kind==='stairs'?field('Floor-to-floor',state.stairHeight,'stairHeight')+field('Width',state.stairWidth,'stairWidth')+field('Risers',state.stairRisers,'stairRisers','')+field('Going',state.stairGoing,'stairGoing')+selectField('Form','stairForm',['Straight','Quarter turn','Half turn'],'Straight'):kind==='level'?field('Elevation',state.typeHeight,'typeHeight')+field('Slab thickness',state.typeThickness,'typeThickness'):field('Width',state.doorWidth,'doorWidth')+field('Height',state.doorHeight,'doorHeight')+(kind==='window'?field('Sill',state.windowSill,'windowSill'):selectField('Swing','doorSwing',['Left inward','Right inward','Left outward','Right outward'],'Left inward'))}${selectField('Material','typeMaterial',['Gypsum / timber stud','Masonry / plaster','Oak','Glass / timber','Birch plywood'],state.typeMaterial)}${button('save-building-type','Save as reusable type','library','small')}<div class="section-label">Placement</div>${kind==='wall'?`<div class="target-box">${icon('plane')}XY · Finished floor</div><div class="drawing-progress">${state.wallDraft.length===0?'1 · Pick start point':state.wallDraft.length===1?'2 · Pick end point':'Segment ready · Apply to add wall'}</div>${button('example-wall','Use example segment','line','small')}${selectField('Justification','wallJustification',['Centerline','Inside face','Outside face'],'Centerline')}`:kind==='stairs'?notice(`Preview: ${(state.stairHeight/state.stairRisers).toFixed(1)} mm rise · ${state.stairRisers} risers. Review local stair requirements before construction.`,'','layers'):`<div class="target-box">${icon('pin')}${kind==='level'?'Footprint on XY plane':'Selected wall · Position along wall'}</div>${field('Along-wall offset',1200,'openingOffset')}`}${check('linkBuildingType','Keep instance linked to saved type',true)}`;}
function measureInspector(){const a=state.measurePicks[0],b=state.measurePicks[1];return `<div class="object-type">${icon('ruler')}Inspection tool</div><h2 class="object-name">Measure</h2><p class="inspector-description">Select two references in the model. Measurement does not add a sketch constraint.</p>${selectField('Pick','measureType',['Faces','Edges','Points'],state.measureType)}${[0,1].map(i=>`<button class="measure-slot ${state.measureSlot===i?'active':''}" data-measure-slot="${i}"><span>${i?'B':'A'}</span><div><strong>${state.measurePicks[i]?esc(state.measurePicks[i].name):'Select a '+(state.measureType==='Faces'?'face':state.measureType==='Edges'?'line / edge':'point')}</strong><small>${i?'Second reference':'First reference'}</small></div>${icon('eye')}</button>`).join('')}${a&&b?`<div class="measurement-result"><small>Minimum distance · Sample geometry</small><strong>${state.project==='makerspace'?roomGap().toLocaleString():state.project==='case'?'12.7':'24.0'} <span>mm</span></strong><div class="measurement-components"><span>ΔX ${state.project==='case'?'12.7':'0.0'}</span><span>ΔY ${state.project==='makerspace'?roomGap():'0.0'}</span><span>ΔZ 0.0</span></div></div>${selectField('Distance','measureDistance',['Minimum separation','Along X','Along Y','Along Z'],'Minimum separation')}${check('pinMeasure','Keep measurement visible',true)}`:notice('Click a visible face or edge. You can change reference A or B at any time.','','ruler')}<div class="section-label">Try a reference pair</div>${button('measure-example',state.project==='makerspace'?'Laser front ↔ bench edge':'Rail face ↔ carcass face','ruler','small')}`;}
function railTransferInspector(op){return operationHeader(op,'Project the actual hardware pattern into the receiving material, using the assembly placement.')+railProjectionDiagram()+`<div class="section-label">Source</div><div class="target-box">${icon('link')}${state.project==='case'?'Drawer rail · Left fixed member':'control-board.kicad_pcb · H1–H4'}</div>${state.project==='case'?selectField('Hole pitch','railPitch',['32','40'],String(state.railPitch)):''}<div class="section-label">Receiving materials</div>${check('railCarcass','Plywood carcass · Inside face',true)}${check('railDrawer','Upper drawer · Outside face',true)}${selectField('Projection','railProjection',['Normal to target face','Along rail mounting axis'],'Normal to target face')}${field('Drill diameter',4,'railDiameter')}${selectField('Carcass cut','railCut',['Blind pilot · 12 mm','Through all'],'Blind pilot · 12 mm')}${check('railAssociative','Keep hardware → drilling relationship',true)}${notice(`Source holes H1–H4 → transformed centers → panel drill features.<br>Change the source pitch to preview how the target holes move.`,'','link')}${state.railLinked?'<span class="pill green">Linked drilling feature created</span>':''}`;}
function railProjectionDiagram(){const pitch=Number(state.railPitch)||32;return `<svg class="technical-diagram" viewBox="0 0 240 132" aria-label="Rail holes projected through a gap onto a wood panel"><path d="M20 18h185v23H20z" fill="#b6c4be" stroke="#75887e"/><path d="M20 88h185v24H20z" fill="#d6bd8e" stroke="#a98d5c"/>${[0,1,2,3].map(i=>{const x=42+i*pitch;return `<circle cx="${x}" cy="30" r="4" fill="#f7f8f1" stroke="#667e72"/><path d="M${x} 39v49" stroke="#b26948" stroke-dasharray="3 3"/><circle cx="${x}" cy="100" r="4" fill="#fff7e8" stroke="#b26948"/>`;}).join('')}<text x="23" y="12">RAIL · SOURCE H1–H4</text><text x="23" y="127">PANEL · LINKED DRILL FEATURES</text><text x="110" y="68" text-anchor="middle">${pitch} mm source pitch</text></svg>`;}
function memberConnectionInspector(op){const style=state.connectionStyle,angle=Number(state.connectionAngle),cut=(180-angle)/2;return operationHeader(op,'A connection owns the end treatments of its participating members. The members remain individual stock parts.')+`<div class="segmented">${['Miter','Cope','Butt'].map(s=>`<button data-connection="${s}" class="${style===s?'active':''}">${s}</button>`).join('')}</div>${weldDiagram(style,angle)}<div class="section-label">Members</div><div class="target-box">${icon('weld')}A · Long rail · SHS 30 × 30 × 2</div><div class="target-box">${icon('weld')}B · Short rail · SHS 30 × 30 × 2</div>${field(style==='Cope'?'Branch angle':'Included angle',state.connectionAngle,'connectionAngle','°')}${field('Weld gap',state.weldGap??.8,'weldGap')}${style==='Miter'?notice(`Equal-width, coplanar example: A end ${cut.toFixed(1)}° + B end ${cut.toFixed(1)}° saw settings. Different profiles require a fitted intersection.`,'','cut'):style==='Cope'?selectField('Treatment','copeTarget',['Trim branch B to member A','Trim both at intersection'],'Trim branch B to member A')+field('Branch offset',0,'branchOffset'):selectField('Through member','weldThrough',['A continues · B terminates','B continues · A terminates'],'A continues · B terminates')}${selectField('Weld','weldProcess',['Fillet · a3','Butt weld','Tack only'],'Fillet · a3')}${check('connectionLinked','Update end cuts when frame path changes',true)}${button('sequence','Author welding order','list','small')}`;}
function weldDiagram(style,angle){return `<svg class="technical-diagram" viewBox="0 0 240 145" aria-label="Two members meet with ${style.toLowerCase()} end treatments"><path d="M24 100h105v24H24z" fill="#9eb2a5" stroke="#6d8977"/><g transform="rotate(${90-angle} 129 100)"><path d="M129 20h24v104h-24z" fill="#bfcabd" stroke="#6d8977"/></g><path d="${style==='Miter'?'M129 100l24 24':style==='Cope'?'M128 94q24 15 0 29':'M128 97v29'}" stroke="#bd6944" stroke-width="3" fill="none"/><path d="M95 102a35 35 0 0 1 35-35" stroke="#a37c43" fill="none"/><text x="95" y="80">${angle}°</text><text x="36" y="96">A</text><text x="163" y="40">B</text><text x="20" y="140">${style==='Miter'?'Paired miter cuts':style==='Cope'?'Branch saddle / fitted end':'One member continues through'}</text></svg>`;}
function sheetToolInspector(op){const h=operationHeader(op);if(op.kind==='base-sheet')return h+`<p class="inspector-description">Start from a profile or convert a constant-thickness solid. Identify the stationary face and bend regions.</p>${selectField('Method','sheetMethod',['From sketch profile','Convert selected solid'],'From sketch profile')}<div class="target-box">${icon('sheet')}${esc(state.selected||'Front panel')} · Stationary base face</div>${selectField('Gauge / stock','sheetStock',['Aluminium 5052 · 2 mm','Steel S235 · 1.5 mm','Stainless 304 · 1 mm'],'Aluminium 5052 · 2 mm')}${field('Thickness',state.sheetThickness,'sheetThickness')}${field('Inside bend radius',state.bendRadius,'bendRadius')}${field('K-factor',.42,'kFactor','')}${notice('Conversion requires constant thickness. Unsupported regions must be split or remodeled.','','info')}`;if(op.kind==='bend')return h+`<div class="target-box">${icon('sheet')}${esc(state.selected||'Front panel')} · Edge chain 1</div>${field('Flange length',24,'flangeHeight')}${field('Angle',90,'bendAngle','°')}${selectField('Direction','bendDirection',['Up','Down'],'Up')}${field('Inside radius',state.bendRadius,'bendRadius')}${selectField('Material side','bendPosition',['Inside dimension','Outside dimension','Bend center'],'Inside dimension')}${selectField('Corner relief','bendRelief',['Round','Rectangular','Tear'],'Round')}${check('flatUpdate','Update associated flat pattern',true)}${button('sheet-check','Review manufacturing checks','check','small')}`;return h+`${selectField('Feature','sheetFeature',op.kind==='sheet-corner'?['Corner relief','Rip / seam','Miter flange corner']:op.kind==='hem'?['Open hem','Closed hem','Jog / offset']:['Cut through','Pocket / emboss','Punch pattern'],op.kind==='sheet-corner'?'Corner relief':op.kind==='hem'?'Open hem':'Cut through')}${field('Size / clearance',2,'sheetFeatureSize')}${check('sheetFeatureFlat','Show in folded and flat representations',true)}${notice('Cut contours, bend directions, reliefs, and seam gaps appear on separate manufacturing layers.','','unfold')}`;}
function guideInspector(op){return operationHeader(op,'Define drawing views in 3D. Guides retain their elevation, viewing direction, and section depth, then generate linked page views.')+`${selectField('View kind','guideKind',['Floor plan','Section','Elevation'],state.guideKind)}${selectField('Reference level','guideLevel',['Ground floor · ±0','Level 02 · +3000','Level 03 · +6000','Custom elevation'],'Custom elevation')}${field('Cut elevation',state.guideHeight,'guideHeight')}${field('View depth',3000,'guideDepth')}${selectField('Look direction','guideDirection',['Down','Up','North','East'],'Down')}${field('Cut offset above level',1200,'guideCutOffset')}${op.kind==='repeat-guides'?field('Level count',8,'guideCount','')+field('Level spacing',3000,'guideSpacing'):''}${check('guideMaterialHatch','Use material section hatches',true)}<div class="section-label">Drawing destination</div><div class="target-box">${icon('drawing')}New linked floor / section pages</div>${button('generate-sheets','Generate from saved guides','drawing','small')}`;}
function sheetInspector(){const s=activeSheet();return `<div class="object-type">${icon('drawing')}Drawing page ${state.activeSheet+1} / ${state.sheets.length}</div><h2 class="object-name">${esc(s.number)}</h2><p class="inspector-description">${esc(s.name)}</p><div class="section-label">Page</div>${selectField('Paper','pagePaper',['A3 landscape','A4 landscape','A4 portrait'],s.paper)}${selectField('Scale','drawingScale',['1:1','1:2','1:5','1:10','1:50','1:100'],s.scale)}<div class="section-label">Title block</div><div class="metadata-line"><span>Drawn by</span><strong>${esc(s.author)}</strong></div><div class="metadata-line"><span>Project</span><strong>${esc(s.project)}</strong></div><div class="metadata-line"><span>Revision</span><strong>${esc(s.revision)}</strong></div><div class="section-label">Linked views</div>${s.views.map((v,i)=>`<button class="list-action" data-sheet-view="${i}">${icon(v.includes('Section')?'section':'drawing')}${esc(v)}${icon('chevron')}</button>`).join('')}${button('add-view','Add view','plus','small')}<div class="section-label">Material representation</div><button class="list-action" data-action="drawing-material">Section hatch from material${icon('wood')}</button><textarea class="full-input" aria-label="Drawing note" data-note rows="3">${esc(s.note)}</textarea>`;}
function exportSetInspector(){const set=state.exportSets[state.activeExportSet];return `<div class="object-type">${icon('folder')}Saved export set</div><h2 class="object-name">${esc(set.name)}</h2><div class="section-label">Selection rule</div><p>${esc(set.match)} · ${set.tags.map(esc).join(' + ')||'All parts'}</p><div class="tags-row">${set.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="section-label">Resolved scope</div><strong>${matchedParts(set).length} matching parts</strong><p class="inspector-description">Names and stable part identities are preserved. Re-running resolves the tags again.</p><div class="section-label">Formats</div>${set.formats.map(f=>`<span class="tag">${f}</span>`).join(' ')}${state.ribbon==='printing'?`<div class="section-label">Print package</div>${selectField('Orientation','printOrientation',['Model placement','Selected build face'],'Model placement')}${check('exportAids','Include removable design aids',set.aids)}${selectField('Mesh','meshQuality',['Fine','Balanced','Coarse'],'Balanced')}${button('edit-fdm','Edit FDM design features','pin','small')}`:''}`;}
const textInput=(label,key,value,extra='')=>`<label class="input-label">${label}<input class="full-input" data-text="${key}" aria-label="${label}" value="${esc(value)}" ${extra}></label>`;
function workflowModalMarkup(){const m=state.modal;if(m==='add-view')return modalWrap('Add drawing view','Select a source and a view. Each placed view can have its own scale.',selectField('Source part / assembly','viewSource',['Current assembly',...projects[state.project].parts],'Current assembly')+selectField('View scale','newViewScale',['1:1','1:2','1:5','1:10','1:50','1:100'],state.newViewScale||activeSheet().scale)+'<div class="option-grid">'+['Front','Top','Right','Isometric','Section A–A','Detail B','Exploded assembly','Flat pattern'].map(v=>'<button data-add-view="'+v+'">'+icon(v.includes('Section')?'section':'drawing')+v+'</button>').join('')+'</div>',button('close-modal','Cancel'));

if(m==='choose-plane')return modalWrap('Choose a sketch plane','Every sketch belongs to a plane. Its external references are evaluated in that plane.',`<div class="plane-choices">${[['XY · Ground floor','Origin / datum'],['XZ · Front plane','Origin / datum'],['YZ · Side plane','Origin / datum'],['Cabinet fronts · Face plane','Selected planar face'],['Offset plane · 18 mm','Offset from selected face']].map(([name,source])=>`<button data-plane="${name}" data-plane-source="${source}" class="plane-choice ${state.plane===name?'active':''}">${icon('plane')}<span><strong>${name}</strong><small>${source}</small></span>${state.plane===name?icon('check'):''}</button>`).join('')}</div>${notice('Coplanar cabinet edges can be projected. A wall crossing the plane contributes an intersection point or line.','','link')}`,`${button('close-modal','Cancel')}${button('start-plane-sketch','Start sketch','sketch','primary')}`,'narrow');
if(m==='building-types')return modalWrap('Architectural type library','Reusable definitions for walls, openings, levels, and stairs.',`<div class="type-library">${state.buildingTypes.map((t,i)=>`<button class="type-card" data-use-type="${i}">${icon(({wall:'room',door:'door',window:'window',level:'plane',stairs:'layers'})[t.kind])}<div><strong>${esc(t.name)}</strong><span>${t.kind.toUpperCase()} · ${esc(t.material)}</span><small>${t.thickness} mm thick · ${t.height} mm high</small></div>${icon('chevron')}</button>`).join('')}</div>`,`${button('close-modal','Done')}`);
if(m==='parameter-help')return modalWrap('Parameters & expressions','Keep design intent in one table.',`<div class="reference-card"><strong>Names</strong><p>Use a unique name such as <code>cabinet_width</code>. The description explains its purpose.</p><strong>Values</strong><p>Enter a value with the chosen unit or reference other parameter names in an expression.</p><code>cabinet_width - 2 * stock_thickness - 2 * rail_gap</code></div>${notice('Expose a parameter to ask for its value when placing a dynamic symbol. Internal dimensions remain in the definition.','','library')}`,`${button('close-modal','Done','','primary')}`,'narrow');
if(m==='page-setup'||m==='add-page'){const s=activeSheet(),add=m==='add-page';return modalWrap(add?'Add drawing page':'Page & title block','Configure each page independently. Views remain linked to the model.',`<div class="two-col"><div>${textInput('Drawing number','draftPageNumber',state.draftPageNumber??(add?'A-'+String(state.sheets.length+1).padStart(3,'0'):s.number))}${textInput('Page title','draftPageName',state.draftPageName??(add?'New fabrication page':s.name))}${selectField('Paper','draftPaper',['A3 landscape','A4 landscape','A4 portrait','A2 landscape'],state.draftPaper||s.paper)}${selectField('Default scale','draftScale',['1:1','1:2','1:5','1:10','1:50','1:100'],state.draftScale||s.scale)}${selectField('Projection','draftProjection',['First angle','Third angle'],state.draftProjection||'First angle')}</div><div><div class="section-label" style="margin-top:0">Drawing information</div>${textInput('Drawn by','draftAuthor',state.draftAuthor??s.author)}${textInput('Project','draftProject',state.draftProject??projects[state.project].name)}${textInput('Revision','draftRevision',state.draftRevision??s.revision)}${textInput('Checked by','draftChecker',state.draftChecker??'')}${check('titleDate','Include issue date',true)}${check('titleMaterial','Include material / process',true)}${check('titlePageCount','Include page number / total',true)}</div></div>`,`${button('close-modal','Cancel')}${button('save-page',add?'Add page':'Apply page settings','check','primary')}`);}
if(m==='drawing-material'||m==='assign-material'){const mat=state.styleMaterial||selectedMaterial(),style=state.materialStyles[mat]||{hatch:'Diagonal',angle:45,spacing:4};return modalWrap(m==='assign-material'?'Assign material':'Material & drawing representation','The same material definition controls stock, basic appearance, and section hatching.',`<div class="two-col"><div>${selectField('Material','styleMaterial',[...new Set([mat,'Birch plywood','Steel · S235','Aluminium · 5052','PETG','Glass','Concrete'])],mat)}${selectField('Section pattern','styleHatch',['Diagonal','Cross hatch','Wood grain','Solid','None'],state.styleHatch||style.hatch)}${field('Hatch angle',state.styleAngle??style.angle,'styleAngle','°')}${field('Hatch spacing',state.styleSpacing??style.spacing,'styleSpacing')}${check('materialGlobal','Update this material across the project',true)}</div><div><div class="hatch-preview" data-hatch="${esc(state.styleHatch||style.hatch)}">${icon('section')}<strong>${esc(mat)}</strong><span>${esc(state.styleHatch||style.hatch)} · Section preview</span></div>${notice('Drawing views inherit the material style. The cut plane determines which parts are hatched.','','link')}</div></div>`,`${button('close-modal','Cancel')}${button('save-material-style',m==='assign-material'?'Assign material':'Save drawing style','check','primary')}`);}
if(m==='sheet-check')return modalWrap('Sheet-metal manufacturing review','Front panel · Folded model and associated flat pattern',`${table(['Check','State','Detail'],[['Thickness','Pass','Constant 2 mm stock'],['Bend definitions','Pass','4 cylindrical bends · Inside R 2 mm'],['Flat contour','Pass','One connected developed blank'],['Reliefs','Pass','All bend ends have relief'],['Hole near bend B2','Review','Check die clearance and process allowance with fabricator'],['Bend allowance','Review','K-factor is a process input, not a universal constant']])}${notice('These are illustrative checks for the UX. Actual manufacturability also depends on tooling, material, and process.','warning')}`,`${button('close-modal','Close')}${button('flat','Inspect flat pattern','unfold','primary')}`);
if(m==='rail-example')return modalWrap('Hardware drives the drilling','Worked example · Drawer rail → plywood carcass → drawer body',`<div class="two-col"><div>${railProjectionDiagram()}<div class="section-label">1 · Place hardware</div><p>The rail has local mounting-hole references H1–H4. Its assembly relationship locates those holes in the project.</p><div class="section-label">2 · Select receiving faces</div><p>Project the hole centers onto the carcass inner face and drawer outer face. Each material can use a different diameter and cut depth.</p></div><div><div class="section-label" style="margin-top:0">3 · Keep the dependency</div><div class="dependency-chain"><span>Rail H1–H4</span>${icon('arrow')}<span>Assembly placement</span>${icon('arrow')}<span>Projected sketch points</span>${icon('arrow')}<span>Panel drill features</span></div>${notice('Changing the rail pattern updates the drill features. Missing source holes produce a repairable reference.','','link')}<span class="pill">Try the 32 → 40 mm pitch preview</span></div></div>`,`${button('close-modal','Close')}${button('start-rail-example','Open linked drilling example','hole','primary')}`);
if(m==='new-export-set'||m==='edit-export-set'){const edit=m==='edit-export-set',s=edit?state.exportSets[state.activeExportSet]:{name:'New manufacturing set',tags:[],match:'All tags',formats:['STEP'],aids:false};return modalWrap(edit?'Edit export set':'Create export set','A saved query plus output recipes. Resolve it again whenever the design changes.',`<div class="two-col"><div>${textInput('Set name','draftSetName',state.draftSetName??s.name)}${textInput('Include part tags','draftSetTags',state.draftSetTags??s.tags.join(', '),'placeholder="wood, cnc"')}${selectField('Matching','draftSetMatch',['All tags','Any tag'],state.draftSetMatch||s.match)}${notice('Part tags are edited in the inspector. Tag selection does not depend on canvas visibility.','','info')}</div><div><div class="section-label" style="margin-top:0">Output formats</div><div class="format-checks">${['PDF','DXF','CSV','STEP','OBJ','3MF','STL','GLB'].map(f=>`<label><input type="checkbox" data-set-format="${f}" ${(state.draftSetFormats||s.formats).includes(f)?'checked':''}>${f}</label>`).join('')}</div>${check('draftSetAids','Include removable FDM design aids',state.draftSetAids??s.aids)}${selectField('Names','exportNaming',['Part name + revision','Part number + revision','Part name only'],'Part name + revision')}</div></div>`,`${button('close-modal','Cancel')}${button('save-export-set','Save export set','check','primary')}`);}
if(m==='set-preview'){const s=state.exportSets[state.activeExportSet],parts=matchedParts(s);return modalWrap('Export package preview',s.name+' · '+parts.length+' matching parts',`<div class="modal-callout">Prototype preview only. No manufacturing files are generated.</div><div class="row" style="margin:18px 0">${s.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}<span class="spacer"></span><span class="pill">Resolved from current project tags</span></div>${s.formats.map(f=>`<div class="output-row"><span class="output-icon">${f}</span><div><strong>${esc(projects[state.project].file)}-${s.name.toLowerCase().replaceAll(' ','-')}.${f.toLowerCase()}</strong><small>${f==='PDF'?state.sheets.length+' linked drawing pages':parts.length+' parts · '+(f==='DXF'?'Contours at 1:1 · CUT / BEND / DRILL':f==='3MF'?(s.aids?'With removable design aids':'Without design aids'):'Names, placements and units retained')}</small></div><span class="spacer"></span><span class="pill">Preview</span></div>`).join('')}${notice(parts.length?'Scope is explicit. Parts outside the tag query are excluded.':'No parts match. Adjust the set or the part tags.','','info')}`,`${button('close-modal','Back')}${button('finish-set','Finish review','check','primary')}`);}
if(m==='dxf-settings'||m==='pdf-settings'||m==='step-settings'||m==='mesh-settings'||m==='print-orientation'||m==='print-aids'){const names={'dxf-settings':'DXF manufacturing layers','pdf-settings':'Drawing page output','step-settings':'STEP solid export','mesh-settings':'Mesh output quality','print-orientation':'Print build orientation','print-aids':'Removable print aids'};return modalWrap(names[m],'Output settings belong to the export recipe.',`${m==='dxf-settings'?check('dxfCut','CUT · Closed outer and inner contours',true)+check('dxfBend','BEND_UP / BEND_DOWN · Center lines',true)+check('dxfDrill','DRILL · Hole centers',true)+check('dxfIds','PART_ID · Labels',true)+notice('Part contours are 1:1. PDF / drawing DXFs preserve each page scale.','','ruler'):m==='pdf-settings'?check('pdfAllPages','All linked drawing pages',true)+check('pdfTitle','Include title blocks and revisions',true)+check('pdfHatch','Use material hatching',true):m==='step-settings'?selectField('Schema','stepSchema',['AP242','AP214'],'AP242')+check('stepHierarchy','Preserve part hierarchy and placements',true):m==='print-orientation'?selectField('Build face','buildFace',['Bottom face','Back face','Selected plane'],'Bottom face')+check('orientCopy','Apply to export placement only',true):m==='print-aids'?check('exportAids','Include breakaway tabs / thin bridges',true)+button('edit-fdm','Edit FDM design geometry','pin','small'):selectField('Mesh quality','meshQuality',['Fine','Balanced','Coarse'],'Balanced')+field('Chord deviation',.1,'meshDeviation')+field('Angular deviation',15,'meshAngle','°')}${notice('Illustrative recipe controls. No slicer or G-code generation is included.','','file')}`,`${button('close-modal','Done','','primary')}`,'narrow');}
if(m==='create-symbol')return modalWrap('Create a parametric symbol','Reuse a part or an assembly. Exposed project parameters become instance inputs.',`<div class="two-col"><div>${textInput('Symbol name','symbolDraftName',state.symbolDraftName||projects[state.project].name)}${selectField('Content','symbolContent',['Selected parts','Whole assembly'],'Whole assembly')}${selectField('Behavior','symbolBehavior',['Dynamic','Static'],state.symbolBehavior||'Dynamic')}${check('symbolPlan','Include simplified plan representation',true)}</div><div><div class="section-label" style="margin-top:0">Parameters to expose</div>${state.parameters.map((p,i)=>`<label class="check-line"><input type="checkbox" data-symbol-expose="${i}" ${p.exposed?'checked':''}><span>${esc(p.name)}<small class="symbol-param-description">${esc(p.description)} · ${esc(p.value)} ${esc(p.unit)}</small></span></label>`).join('')}${button('parameters','Open parameter table','sliders','small')}</div></div>`,`${button('close-modal','Cancel')}${button('save-symbol','Create library symbol','library','primary')}`);
if(m==='mcp'||m==='connections')return mcpModal();
if(m==='tour')return revisedTourModal();
return null;}
function mcpModal(){const pending=state.mcpPending;return modalWrap('MCP control & activity','External assistants operate the application. There is no built-in AI chat.',`<div class="modal-tabs">${[['pending','Pending'],['activity','Activity history'],['connection','Connection']].map(([id,l])=>`<button data-mcp-tab="${id}" class="${state.mcpTab===id?'active':''}">${l}${id==='pending'&&pending?' · 1':''}</button>`).join('')}</div>${state.mcpTab==='connection'?`<div class="modal-callout">UX prototype · No MCP server is running. These controls show the planned connection experience.</div><div class="setting-row"><div><strong>Local MCP endpoint</strong><small>Native transport · Current project only</small></div><input class="toggle" type="checkbox" data-toggle="mcp" ${state.mcp?'checked':''} aria-label="Local MCP endpoint"></div>${check('mcpRead','Inspect models, parameters, references and measurements',true)}${check('mcpPreview','Create operation previews',true)}${check('mcpEdit','Apply reviewed transactions',true)}${check('mcpExport','Write exports to configured folders',false)}${selectField('Edit policy','mcpPolicy',['Review transactions','Trusted session'],'Review transactions')}${notice('Remote control requires separate authenticated configuration. Units, target IDs, and project revision accompany modeling commands.','','lock')}`:state.mcpTab==='activity'?`<div class="audit-list">${mcpAudit.length?mcpAudit.map(a=>`<div class="audit-row"><span class="audit-icon">${icon(a.status==='Applied'?'check':a.status==='Undone'?'undo':'eye')}</span><div><strong>${esc(a.label)}</strong><small>${a.client} · ${a.time} · ${a.tools}</small></div><span class="pill">${a.status}</span></div>`).join(''):'<div class="empty-result"><strong>No MCP actions in this prototype session</strong><p>Preview a sample external request to inspect the activity flow.</p></div>'}</div>`:pending?`<div class="mcp-client"><span class="avatar">EX</span><div><strong>Example external client</strong><small>Transaction tx-0042 · Base revision ${pending.base}</small></div><span class="pill orange">Awaiting review</span></div>${table(['Tool','Target','Change'],[['model.inspect','Rail H1–H4','Read source identities'],['sketch.project','Carcass inner face','4 linked hole centers · mm'],['feature.drill','Plywood carcass','Ø 4 · Blind 12 mm']])}${notice('Inspect the proposed geometry before applying. The group commits as one undoable operation.','','branch')}`:`<div class="empty-result"><span class="connection-ring">${icon('branch')}</span><strong>No pending external actions</strong><p>Incoming requests identify the client, tools, target parts, units, and proposed changes.</p>${button('mcp-sample','Preview a sample request','play','primary')}</div>`}`,`${button('close-modal','Close')}${pending&&state.mcpTab==='pending'?button('mcp-inspect','Inspect in model','eye','primary'):''}`);}
function mcpInspector(){return `<div class="object-type">${icon('branch')}Example external client</div><h2 class="object-name">Linked rail drilling</h2><span class="pill orange">MCP transaction tx-0042</span><p class="inspector-description">No geometry is committed yet. Review the targets and tool arguments.</p>${state.mcpPending?.stale?notice('Project revision changed. Refresh this preview before applying.','warning')+button('mcp-refresh','Refresh preview','refresh','small'):''}${railProjectionDiagram()}<div class="section-label">Proposed operations</div>${['Inspect rail H1–H4','Project centers onto carcass inner face','Drill 4 holes · Ø 4 mm · 12 mm deep'].map(v=>`<div class="ai-command">${icon('arrow')}${v}</div>`).join('')}<div class="section-label">Transaction</div><div class="metadata-line"><span>Units</span><strong>mm</strong></div><div class="metadata-line"><span>Target ID</span><code>part:carcass-01</code></div><div class="metadata-line"><span>Revision</span><strong>${state.mcpPending?.base??0}</strong></div>${button('mcp','Full request & activity','branch','small')}`;}
function revisedTourModal(){const items=[['makerspace','parameters','sliders','Name the design','Editable parameters, descriptions, expressions, and exposed symbol inputs.'],['console','sketch','sketch','Sketch on a plane','Project cabinet edges or intersect a crossing wall. Reuse multiple profiles.'],['makerspace','architecture','room','Reusable building types','Walls, doors, windows, levels, and stairs share type definitions.'],['table','wood','wood','Cabinetry that connects','Stock-based panels, carcasses, grooves, multi-panel joints, and face-to-face stacks.'],['console','sheet','sheet','Sheet metal to manufacture','Stationary faces, bends, reliefs, process checks, and linked flat patterns.'],['table','weld','weld','Members to weldment','Paired miters, branch copes, gap, weld definition, end cuts, and authored weld order.'],['case','assembly','link','Hardware drives the holes','Rail mounting holes project into wood and drawer material, with a live dependency.'],['tower','guides','plane','Define drawings in 3D','Cut levels and section planes become linked pages with material hatching.'],['console','drawings','drawing','Build a drawing set','Multiple independent pages, view scales, title blocks, dimensions, and notes.'],['console','render','eye','Prepare a render','Basic display, material appearance, camera, and Blender handoff.'],['case','printing','print','Print deliverables','Model design aids; export orientation, meshes, removable aids, and 3MF.'],['table','export','download','Repeat exports by tags','Saved selection rules resolve manufacturing and 3D output packages.']];return modalWrap('Explore the revised workflows','Colored modes define the stage. Ribbon tabs expose the domain tools.',`<div class="tour-grid">${items.map(([p,w,i,n,d])=>`<button class="tour-card" data-workflow="${p}:${w}">${icon(i)}<strong>${n}</strong><p>${d}</p></button>`).join('')}</div><div class="filter-row" style="margin-top:20px">${button('measure','Measure two references','ruler','small')}${button('library','Symbol library','library','small')}${button('mcp','MCP preview & history','branch','small')}</div>`,`${button('close-modal','Back to design','','primary')}`,'wide');}
function beginTool(kind,label,opts={}){state.operation={kind,label,...opts};state.modal=null;state.measure=false;state.sheetSelected=false;state.exportSetSelected=false;if(kind==='extrude'){state.mode='model';state.ribbon='common';state.workspace='sketch';state.view='sketch';}else if(['wall','door','window','level','stairs'].includes(kind)){if(state.mode!=='sketch')state.mode='model';state.ribbon='architecture';state.workspace='room';state.view='plan';const idx=state.buildingTypes.findIndex(t=>t.kind===kind);loadBuildingType(idx);state.wallDraft=[];}else if(['joint','panel','carcass','laminate','groove','panel-drill','panel-edges'].includes(kind)){state.mode='model';state.ribbon='wood';state.workspace='wood';state.view='3d';}else if(['base-sheet','bend','sheet-corner','hem','cutout'].includes(kind)){state.mode='model';state.ribbon='sheet';state.workspace='sheet';state.view='3d';state.flat=false;}else if(['profile','member-connection','cope','weld-joint','frame-path'].includes(kind)){state.mode='model';state.ribbon='weld';state.workspace='weld';state.view='3d';if(kind==='cope')state.connectionStyle='Cope';}else if(['support','bridge','custom-support','clearance'].includes(kind)){state.mode='model';state.ribbon='print';state.workspace='print';state.view='3d';}else if(['floor-guide','section-guide','elevation-guide','repeat-guides'].includes(kind)){state.mode='model';state.ribbon='guides';state.workspace='model';state.view='3d';state.guideKind=kind==='section-guide'?'Section':kind==='elevation-guide'?'Elevation':'Floor plan';}else if(kind==='relationship'){state.mode='model';state.ribbon='assembly';state.workspace='assembly';state.view='3d';}else if(kind==='holes'){state.mode='model';state.ribbon=state.project==='case'?'assembly':'common';state.workspace=state.project==='case'?'assembly':'model';state.view='3d';}render();}
function loadBuildingType(i){const t=state.buildingTypes[i];if(!t)return;state.typeIndex=i;state.typeName=t.name;state.typeThickness=t.thickness;state.typeMaterial=t.material;state.typeHeight=t.height;state.doorWidth=t.width||900;state.doorHeight=t.height||2100;}
function recordAudit(label,status,tools){mcpAudit.unshift({label,status,client:'Example external client',time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}),tools});}
function clearPageDraft(){for(const k of ['draftPageNumber','draftPageName','draftPaper','draftScale','draftAuthor','draftProject','draftRevision','draftChecker','draftProjection'])delete state[k];}
function clearSetDraft(edit){const s=edit?state.exportSets[state.activeExportSet]:{name:'New manufacturing set',tags:[],match:'All tags',formats:['STEP'],aids:false};Object.assign(state,{draftSetName:s.name,draftSetTags:s.tags.join(', '),draftSetMatch:s.match,draftSetFormats:[...s.formats],draftSetAids:s.aids});}
function workflowAction(action){const op=state.operation;
if(action==='parameters'){switchMode('parameters');return;}if(action==='export'){switchMode('export');state.exportSetSelected=true;render();return;}
if(action==='ai'||action==='connections'||action==='mcp'){state.modal='mcp';renderModal();return;}
if(action==='measure'){state.measure=true;state.measureSlot=0;state.measurePicks=[];state.operation=null;state.modal=null;state.sheetSelected=false;state.exportSetSelected=false;if(['parameters','export'].includes(state.mode))switchMode('model');state.measure=true;render();return;}
if(action==='close-measure'||action==='clear-selection'){state.measure=false;state.measurePicks=[];state.operation=null;state.selected=null;state.selection=[];state.sheetSelected=false;state.exportSetSelected=false;render();return;}
if(action==='measure-reset'){state.measurePicks=[];state.measureSlot=0;render();return;}
if(action==='measure-example'){state.measurePicks=state.project==='makerspace'?[{name:'Laser cutter · Front face'},{name:'Assembly bench · Back edge'}]:[{name:'Rail · Mounting face'},{name:'Plywood carcass · Inner face'}];state.measureSlot=1;render();return;}
if(['choose-plane','new-sketch','open-sketch'].includes(action)){if(action==='new-sketch'&&state.selected){state.plane=state.selected+' · Face plane';state.planeSource='Selected planar face';}state.modal='choose-plane';renderModal();return;}
if(action==='start-plane-sketch'){state.mode='sketch';state.ribbon='common';state.workspace='sketch';state.view='sketch';state.selected='Master sketch';state.selection=[];state.modal=null;state.operation=null;render();return;}
if(action==='sketch-references'){beginTool('sketch-references','Project / intersect references');return;}
if(action==='reference-coplanar'||action==='reference-intersection'){const n=action==='reference-coplanar'?'Neighbor cabinet front · Coplanar edge E12':'Crossing wall · Plane intersection P4';if(!state.sketchReferences.includes(n))state.sketchReferences.push(n);render();return;}
if(['edge-treatment','panel','carcass','groove','panel-drill','laminate','member-connection','sheet-corner','hem','floor-guide','section-guide','elevation-guide','repeat-guides','stairs','render-style','render-camera','custom-support'].includes(action)){beginTool(action,{'edge-treatment':'Fillet / chamfer',panel:'Create stock panel',carcass:'Carcass / shelves',groove:'Groove / rabbet','panel-drill':'Drill / pocket',laminate:'Stack / glue panels','member-connection':'Member connection','sheet-corner':'Corner / seam',hem:'Hem / jog','floor-guide':'Floor plan guide','section-guide':'Section plane','elevation-guide':'Elevation guide','repeat-guides':'Repeat drawing guides',stairs:'Place stairs','render-style':'Viewport appearance','render-camera':'Camera setup','custom-support':'Custom removable support'}[action]);return;}
if(action==='material'){beginTool('panel-edges','Grain & edge treatment');return;}if(action==='toggle-edge-style'){state.edgeStyle=state.edgeStyle==='Fillet'?'Chamfer':'Fillet';render();return;}
if(action==='building-types'||action==='parameter-help'||action==='sheet-check'||action==='rail-example'||action==='drawing-material'||action==='assign-material'){state.modal=action;if(action==='drawing-material'||action==='assign-material'){state.styleMaterial=selectedMaterial();delete state.styleHatch;delete state.styleAngle;delete state.styleSpacing;}renderModal();return;}
if(action==='save-building-type'){const type={kind:op.kind,name:state.typeName,thickness:state.typeThickness,material:state.typeMaterial,height:state.typeHeight,width:state.doorWidth};commit('Save reusable '+op.kind+' type',()=>state.buildingTypes.push(type));state.typeIndex=state.buildingTypes.length-1;state.operation=op;render();return;}
if(action==='example-wall'){state.wallDraft=[{x:300,y:180},{x:300,y:380}];render();return;}
if(action==='start-rail-example'){go('case','assembly');state.selected='Plywood carcass';state.selection=['Plywood carcass','Upper drawer'];beginTool('holes','Transfer rail mounting holes',{icon:'hole'});return;}
if(action==='show-dependencies'){beginTool('dependencies','Sources & dependents',{icon:'link'});return;}
if(action==='flat'){if(!state.selected||!selectedMaterial().includes('Aluminium')&&!selectedMaterial().includes('Steel')){const p=projects[state.project],i=p.materials.findIndex(m=>m.includes('Aluminium')||m.includes('Steel'));if(i<0){toast('Select a sheet-metal part. The Control desk sample contains one.');return;}state.selected=p.parts[i];state.selection=[state.selected];}state.mode='model';state.ribbon='sheet';state.workspace='sheet';state.flat=true;state.view='plan';state.modal=null;state.operation=null;render();toast('Associated flat pattern of '+state.selected+' · Folded part preserved.');return;}
if(action==='folded'){state.flat=false;state.view='3d';state.mode='model';state.ribbon='sheet';state.workspace='sheet';render();return;}
if(action==='motion'){state.mode='model';state.ribbon='assembly';state.workspace='assembly';state.view='3d';state.operation={kind:'motion-controls',label:'Assembly motion'};state.modal=null;render();return;}
if(action==='add-parameter'){commit('Add parameter',()=>state.parameters.push({name:'parameter_'+(state.parameters.length+1),description:'',value:'0',unit:'mm',exposed:false}));return;}
if(action==='exposed-only'){state.exposedOnly=!state.exposedOnly;render();return;}
if(action==='copy-part'){const names=state.selection.length?state.selection:[state.selected];commit('Copy '+names.length+' parts',()=>{for(const n of names){const name=n+' copy';state.placed.push(name);state.partTags[state.project+':'+name]=[...tagsFor(n)];}state.selected=state.placed.at(-1);state.selection=[state.selected];});return;}
if(action==='add-page'||action==='page-setup'){clearPageDraft();state.modal=action;renderModal();return;}
if(action==='save-page'){const add=state.modal==='add-page',s=activeSheet();const page={...clone(s),number:state.draftPageNumber??(add?'A-'+String(state.sheets.length+1).padStart(3,'0'):s.number),name:state.draftPageName??(add?'New fabrication page':s.name),paper:state.draftPaper||s.paper,scale:state.draftScale||s.scale,author:state.draftAuthor??s.author,project:state.draftProject??projects[state.project].name,revision:state.draftRevision??s.revision,checker:state.draftChecker||'',projection:state.draftProjection||'First angle',views:add?[]:s.views};commit(add?'Add drawing page':'Configure drawing page',()=>{if(add){state.sheets.push(page);state.activeSheet=state.sheets.length-1;}else state.sheets[state.activeSheet]=page;state.modal=null;state.mode='drawings';state.workspace='drawings';state.ribbon='common';state.sheetSelected=true;state.selected=null;});return;}
if(action==='duplicate-page'){commit('Duplicate drawing page',()=>{const s=clone(activeSheet());s.number='A-'+String(state.sheets.length+1).padStart(3,'0');s.name+=' · Copy';state.sheets.push(s);state.activeSheet=state.sheets.length-1;});return;}
if(action==='save-material-style'){const mat=state.styleMaterial||selectedMaterial(),existing=state.materialStyles[mat]||{hatch:'Diagonal',angle:45,spacing:4};commit('Update material drawing style',()=>{state.materialStyles[mat]={hatch:state.styleHatch||existing.hatch,angle:state.styleAngle??existing.angle,spacing:state.styleSpacing??existing.spacing};if(state.mode==='drawings')activeSheet().material=mat;if(state.modal==='assign-material'){state.materialAssignments||={};for(const n of state.selection.length?state.selection:[state.selected])state.materialAssignments[state.project+':'+n]=mat;}state.modal=null;});return;}
if(action==='generate-sheets'){if(!state.guides.length){toast('Save a 3D drawing guide first.');beginTool('floor-guide','Floor plan guide');return;}commit('Generate linked drawing pages',()=>{for(const g of state.guides){if(state.sheets.some(s=>s.guideId===g.id))continue;state.sheets.push({number:'GA-'+String(state.sheets.length+1).padStart(3,'0'),name:g.kind+' · +'+g.height+' mm',paper:'A3 landscape',scale:'1:50',author:'Tobias Keller',project:projects[state.project].name,revision:'A',views:[g.kind+' · +'+g.height],guideId:g.id,note:'View derived from 3D drawing guide.'});}state.activeSheet=state.sheets.length-1;state.mode='drawings';state.workspace='drawings';state.ribbon='common';state.sheetSelected=true;state.selected=null;state.view='sheet';});return;}
if(action==='new-export-set'||action==='edit-export-set'){clearSetDraft(action==='edit-export-set');state.modal=action;renderModal();return;}
if(action==='save-export-set'){if(!state.draftSetFormats.length){toast('Choose at least one output format.');return;}const editing=state.modal==='edit-export-set';commit('Save export set',()=>{const s={name:state.draftSetName||'Export set',tags:parseTags(state.draftSetTags),match:state.draftSetMatch,formats:[...state.draftSetFormats],aids:!!state.draftSetAids};if(editing)state.exportSets[state.activeExportSet]=s;else{state.exportSets.push(s);state.activeExportSet=state.exportSets.length-1;}state.modal=null;state.mode='export';state.ribbon='common';state.exportSetSelected=true;state.selected=null;state.selection=[];});return;}
if(action==='preview-set'){state.modal='set-preview';renderModal();return;}
if(action==='validate-set'){const count=matchedParts(state.exportSets[state.activeExportSet]).length;toast(count?`${count} tagged parts resolved · ${state.sheets.length} linked pages · Prototype checks only.`:'No parts match this set. Edit tags or the query.');return;}
if(action==='finish-set'){state.modal=null;renderModal();toast('Package review complete. No manufacturing files were generated.');return;}
if(['dxf-settings','pdf-settings','step-settings','mesh-settings','print-orientation','print-aids'].includes(action)){state.modal=action;renderModal();return;}
if(action==='print-export'){switchMode('export');state.ribbon='printing';state.activeExportSet=2;state.exportSetSelected=true;render();return;}
if(action==='edit-fdm'){switchMode('model');switchRibbon('print');return;}
if(action==='flat-view'){state.modal='add-view';renderModal();return;}
if(action==='weld-note'){state.drawingNote='Weld all indicated joints. See authored weld sequence.';state.modal='annotation';renderModal();return;}
if(action==='save-camera'){commit('Save viewport camera',()=>state.renderCamera='Saved perspective');return;}
if(action==='save-symbol'){const exposed=state.parameters.filter(p=>p.exposed).map(p=>p.name);commit('Create library symbol',()=>{state.customSymbols||=[];const id='custom-'+(state.customSymbols.length+1),dynamic=state.symbolBehavior!=='Static';state.customSymbols.push([id,state.symbolDraftName||projects[state.project].name,(dynamic?'Dynamic':'Static')+' · Project definition','wood',dynamic?exposed:[]]);state.symbol=id;state.symbolFilter='All';state.symbolSearch='';state.modal='library';});return;}
if(action==='mcp-sample'){go('case','assembly');state.mcpPending={base:state.changes,project:'case'};recordAudit('Preview rail drilling','Previewed','model.inspect → sketch.project → feature.drill');state.modal='mcp';state.mcpTab='pending';render();return;}
if(action==='mcp-inspect'){state.modal=null;beginTool('mcp-drill','Linked rail drilling',{fromMcp:true,icon:'branch'});state.workspace='assembly';state.ribbon='assembly';state.mode='model';state.selected='Plywood carcass';render();return;}
if(action==='mcp-refresh'){if(state.mcpPending){state.mcpPending.base=state.changes;state.mcpPending.stale=false;}render();return;}if(action==='mcp-apply'){if(!state.mcpPending)return;if(state.mcpPending.base!==state.changes){toast('The project changed. Preview this transaction again against the current revision.');state.mcpPending.stale=true;render();return;}recordAudit('Linked rail drilling','Applied','feature.drill · part:carcass-01');commit('MCP · Linked rail drilling',()=>{state.railLinked=true;state.mcpPending=null;});return;}
if(action==='apply-op'&&op){if(op.kind==='wall'&&state.wallDraft.length<2){toast('Choose two points on the floor plane first.');return;}if(['wall','door','window','level','stairs','holes','joint','carcass','panel','laminate','groove','panel-drill','member-connection','cope','weld-joint','base-sheet','sheet-corner','hem','edge-treatment','sketch-references','floor-guide','section-guide','elevation-guide','repeat-guides','render-style','render-camera','drawing-view','dependencies','motion-controls'].includes(op.kind)){commit(op.label,()=>{if(op.kind==='wall'){state.customWalls.push({points:clone(state.wallDraft),thickness:state.typeThickness,type:state.typeName,material:state.typeMaterial});state.placed.push(state.typeName+' · Wall '+state.customWalls.length);}else if(['door','window','level','stairs'].includes(op.kind)){state.buildingPlacements.push({kind:op.kind,type:state.typeName});state.placed.push(state.typeName+' · '+state.buildingPlacements.length);}if(op.kind==='holes')state.railLinked=true;if(op.kind==='panel'||op.kind==='carcass')state.placed.push(op.kind==='panel'?'New stock panel':'Carcass assembly');if(op.kind==='edge-treatment')state.edgeApplied=true;if(['floor-guide','section-guide','elevation-guide','repeat-guides'].includes(op.kind)){const count=op.kind==='repeat-guides'?Math.max(1,Math.min(30,state.guideCount||8)):1;for(let i=0;i<count;i++)state.guides.push({id:'guide-'+(state.guides.length+1),height:state.guideHeight+i*(state.guideSpacing||3000),kind:state.guideKind});}state.wallDraft=[];});return;}}
if(action==='add-annotation'){const note=document.getElementById('annotation-text')?.value||state.drawingNote;commit('Add drawing annotation',()=>{state.drawingNote=note;activeSheet().note=note;state.modal=null;});return;}
if(action==='undo'||action==='redo'){const mcpChange=state.history.at(-1)?.startsWith('MCP');legacyAct(action);if(mcpChange&&action==='undo')recordAudit('Undo linked rail drilling','Undone','document.undo');return;}
legacyAct(action);
if(action==='apply-op'){state.mode='model';state.selection=state.selected?[state.selected]:[];render();}
}
function parseTags(value){return [...new Set(String(value||'').split(',').map(t=>t.trim().toLowerCase()).filter(Boolean))];}
const projectSessions={};let pristineDocument;
function openProject(project,workspace){const sharedTypes=clone(state.buildingTypes),sharedSymbols=clone(state.customSymbols||[]);if(pristineDocument){projectSessions[state.project]=clone(state);state=clone(projectSessions[project]||pristineDocument);}const p=projects[project];state.buildingTypes=[...state.buildingTypes,...sharedTypes.filter(t=>!state.buildingTypes.some(b=>b.name===t.name))];state.customSymbols=[...(state.customSymbols||[]),...sharedSymbols.filter(s=>!(state.customSymbols||[]).some(b=>b[0]===s[0]))];state.project=project;state.workspace=workspace||p.workspace;state.selected=p.selected;state.selection=[p.selected];state.modal=null;state.operation=null;state.measure=false;state.manufacturing=null;state.sheets.forEach(s=>s.project=p.name);if(!projectSessions[project]){state.sheets[0].views=project==='makerspace'?['Floor plan']:['Front','Right','Section A–A','Isometric'];state.sheets[0].name=project==='makerspace'?'Ground floor equipment plan':p.name+' · Fabrication';}if(!projectSessions[project])state.history=project==='makerspace'?['Room outline','Wall height','Entry door','South window','Assembly bench','Laser cutter','Service clearance']:project==='case'?['Carcass','Drawers','Rail placement','Mounting references']:['Master sketch','Parts','Connections','Material definitions'];state.view=state.workspace==='room'?'plan':state.workspace==='sketch'?'sketch':state.workspace==='drawings'?'sheet':'3d';state.sheetSelected=state.workspace==='drawings';state.flat=false;state.section=false;undoStack.length=0;redoStack.length=0;syncWorkflowContext();document.getElementById('toast').classList.remove('visible');render();}
function workflowClick(e){if(suppressSceneClick){suppressSceneClick=false;render();return;}const el=e.target.closest('[data-mode],[data-ribbon],[data-sheet],[data-export-set],[data-edge-style],[data-measure-slot],[data-plane],[data-use-type],[data-connection],[data-workflow],[data-delete-param],[data-sheet-view],[data-symbol-expose]');if(el){if(el.dataset.mode){switchMode(el.dataset.mode);return;}if(el.dataset.ribbon){switchRibbon(el.dataset.ribbon);return;}if(el.dataset.sheet!==undefined){state.activeSheet=Number(el.dataset.sheet);state.sheetSelected=true;state.selected=null;state.operation=null;state.drawingScale=activeSheet().scale;state.drawingNote=activeSheet().note;render();return;}if(el.dataset.exportSet!==undefined){state.activeExportSet=Number(el.dataset.exportSet);state.exportSetSelected=true;state.selected=null;state.selection=[];render();return;}if(el.dataset.edgeStyle){state.edgeStyle=el.dataset.edgeStyle;render();return;}if(el.dataset.measureSlot!==undefined){state.measureSlot=Number(el.dataset.measureSlot);render();return;}if(el.dataset.plane){state.plane=el.dataset.plane;state.planeSource=el.dataset.planeSource;renderModal();return;}if(el.dataset.useType!==undefined){const i=Number(el.dataset.useType),kind=state.buildingTypes[i].kind;beginTool(kind,{wall:'Draw wall',door:'Place door',window:'Place window',level:'Level / pedestal',stairs:'Place stairs'}[kind]);loadBuildingType(i);render();return;}if(el.dataset.connection){state.connectionStyle=el.dataset.connection;render();return;}if(el.dataset.deleteParam!==undefined){commit('Remove parameter',()=>state.parameters.splice(Number(el.dataset.deleteParam),1));return;}if(el.dataset.sheetView!==undefined){state.operation={kind:'drawing-view',label:'Drawing view · '+activeSheet().views[Number(el.dataset.sheetView)],viewIndex:Number(el.dataset.sheetView)};state.sheetSelected=false;render();return;}if(el.dataset.workflow){const [p,w]=el.dataset.workflow.split(':');go(p);if(['parameters','sketch','drawings','render','export'].includes(w))switchMode(w);else if(w==='printing'){switchMode('export');state.ribbon='printing';state.activeExportSet=2;state.exportSetSelected=true;render();}else{switchMode('model');switchRibbon(w);}return;}}
const mcpTab=e.target.closest('[data-mcp-tab]');if(mcpTab){state.mcpTab=mcpTab.dataset.mcpTab;renderModal();return;}
const view=e.target.closest('[data-add-view]');if(view){commit('Add drawing view',()=>{activeSheet().views.push(view.dataset.addView);state.viewScales||={};state.viewScales[activeSheet().number+':'+(activeSheet().views.length-1)]=state.newViewScale||activeSheet().scale;state.modal=null;state.mode='drawings';state.workspace='drawings';state.sheetSelected=true;});return;}
if(state.operation?.kind==='wall'&&e.target.closest('#scene')){const svg=document.getElementById('scene').querySelector('svg');const point=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());if(state.wallDraft.length===2)state.wallDraft=[];state.wallDraft.push({x:Math.round(point.x/5)*5,y:Math.round(point.y/5)*5});render();return;}const part=e.target.closest('[data-part]');if(part){const name=part.dataset.part;if(state.measure){state.measurePicks[state.measureSlot]={name:name+' · '+({Faces:'Face',Edges:'Edge',Points:'Point'})[state.measureType]+' '+(e.target.dataset.face||1)};state.measureSlot=state.measureSlot===0?1:0;render();return;}if(state.operation?.kind==='sketch-references'){if(!state.sketchReferences.includes(name+' · Projected edge'))state.sketchReferences.push(name+' · Projected edge');render();return;}if(state.operation){state.selection=state.selection.includes(name)?state.selection.filter(n=>n!==name):[...state.selection,name];state.selected=name;render();return;}state.selected=name;state.selection=e.metaKey||e.ctrlKey?(state.selection.includes(name)?state.selection.filter(n=>n!==name):[...state.selection,name]):[name];state.operation=null;state.sheetSelected=false;state.exportSetSelected=false;render();return;}
const sceneEl=e.target.closest('#scene');if(sceneEl&&!e.target.closest('button,input,select,[data-action],[data-profile]')){if(state.operation?.kind==='wall'){const svg=sceneEl.querySelector('svg');const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());if(state.wallDraft.length===2)state.wallDraft=[];state.wallDraft.push({x:Math.round(p.x/5)*5,y:Math.round(p.y/5)*5});render();return;}if(state.measure&&['path','rect','line','polygon','circle'].includes(e.target.tagName.toLowerCase())){state.measurePicks[state.measureSlot]={name:(state.workspace==='room'?'Room boundary':'Model geometry')+' · '+state.measureType.slice(0,-1)};state.measureSlot=1-state.measureSlot;render();return;}if(!state.operation&&state.mode!=='drawings'&&!['parameters','export'].includes(state.mode)){state.selected=null;state.selection=[];render();return;}}
const feature=e.target.closest('[data-feature]');if(feature?.dataset.feature==='Fillet / chamfer'){act('edge-treatment');return;}legacyHandleClick(e);}
function workflowChange(e){const el=e.target;if(el.dataset.field){const value=Number(el.value);if(Number.isFinite(value)){state[el.dataset.field]=value;renderScene();}return;}if(el.dataset.multiPart){const name=el.dataset.multiPart;state.selection=el.checked?[...new Set([...state.selection,name])]:state.selection.filter(n=>n!==name);state.selected=state.selection.at(-1)||null;render();return;}if(el.dataset.param){if(parameterEditElement===el){parameterEditElement=null;return;}const [i,k]=el.dataset.param.split(':'),v=k==='exposed'?el.checked:el.value;if(k==='name'&&(!/^[A-Za-z_]\w*$/.test(v)||state.parameters.some((p,j)=>j!==Number(i)&&p.name===v))){toast('Use a unique parameter name with letters, digits, and underscores.');render();return;}commit('Edit parameter '+(state.parameters[i].name||'value'),()=>state.parameters[i][k]=v);return;}if(el.hasAttribute('data-part-tags')){if(tagEditElement===el){tagEditElement=null;return;}const names=state.selection.length?state.selection:[state.selected];commit('Tag '+names.length+' parts',()=>{for(const n of names)state.partTags[state.project+':'+n]=parseTags(el.value);});return;}if(el.dataset.buildingType!==undefined){loadBuildingType(Number(el.value));render();return;}if(el.dataset.symbolExpose!==undefined){state.parameters[Number(el.dataset.symbolExpose)].exposed=el.checked;return;}if(el.dataset.setFormat){const f=el.dataset.setFormat;state.draftSetFormats=el.checked?[...new Set([...state.draftSetFormats,f])]:state.draftSetFormats.filter(v=>v!==f);return;}if(el.dataset.text){state[el.dataset.text]=el.value;return;}
if(el.dataset.select){const key=el.dataset.select;state[key]=el.value;if(key==='selectedViewScale'&&state.operation){state.viewScales||={};state.viewScales[activeSheet().number+':'+state.operation.viewIndex]=el.value;}if(key==='pagePaper')activeSheet().paper=el.value;if(key==='drawingScale'){activeSheet().scale=el.value;state.drawingScale=el.value;}if(key==='styleMaterial'){delete state.styleHatch;delete state.styleAngle;delete state.styleSpacing;}if(['styleMaterial','styleHatch'].includes(key)){renderModal();return;}if(key==='renderCamera')state.view=el.value==='Top'?'plan':'3d';if(key==='renderStyle'||key==='renderBackground'||key==='renderCamera'){render();return;}if(key==='railPitch'||key==='measureType'){render();return;}}
legacyHandleChange(e);if(el.dataset.field){if(['connectionAngle','guideHeight','stairRisers','stairHeight'].includes(el.dataset.field))render();if(['styleAngle','styleSpacing'].includes(el.dataset.field))renderModal();}if(el.dataset.toggle==='exportAids'){state.exportSets[state.activeExportSet].aids=el.checked;render();}}
let parameterEditElement=null,tagEditElement=null;
function workflowInput(e){const el=e.target;if(el.dataset.field){const value=Number(el.value);if(Number.isFinite(value)){state[el.dataset.field]=value;renderScene();if(el.dataset.field==='connectionAngle'){const diagram=app.querySelector('.technical-diagram');if(diagram)diagram.outerHTML=weldDiagram(state.connectionStyle,value);if(state.connectionStyle==='Miter'){const summary=app.querySelector('.inspector-content .notice');if(summary)summary.outerHTML=notice('Equal-width, coplanar example: A end '+((180-value)/2).toFixed(1)+'° + B end '+((180-value)/2).toFixed(1)+'° saw settings. Different profiles require a fitted intersection.','','cut');}}}return;}if(el.hasAttribute('data-part-tags')){if(tagEditElement!==el){undoStack.push(clone(state));redoStack.length=0;state.history.push('Edit part tags');state.changes++;state.saved=false;tagEditElement=el;}for(const name of state.selection.length?state.selection:[state.selected])state.partTags[state.project+':'+name]=parseTags(el.value);return;}if(el.dataset.param&&el.tagName==='INPUT'&&el.type!=='checkbox'){const [i,k]=el.dataset.param.split(':');if(parameterEditElement!==el){undoStack.push(clone(state));redoStack.length=0;state.history.push('Edit parameter '+state.parameters[i].name);state.changes++;state.saved=false;parameterEditElement=el;}state.parameters[i][k]=el.value;for(const cell of app.querySelectorAll('.parameter-table td:nth-child(3)')){const input=cell.querySelector('[data-param]');if(input){const row=Number(input.dataset.param.split(':')[0]);cell.querySelector('small').textContent=parameterResult(state.parameters[row]);}}const saved=app.querySelector('.save-state');if(saved){saved.textContent='Unsaved';saved.classList.add('orange');}const undo=app.querySelector('[data-action="undo"]');if(undo)undo.disabled=false;return;}if(e.target.dataset.text)state[e.target.dataset.text]=e.target.value;if(e.target.dataset.note!==undefined){activeSheet().note=e.target.value;state.drawingNote=e.target.value;}legacyHandleInput(e);}
function keyboardWorkflow(e){if(e.key==='Tab'&&state.modal){const root=overlays.querySelector('[role=dialog]'),items=root?.querySelectorAll('button:not(:disabled),input,select,textarea');if(items?.length){const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(e.key==='Escape'){if(state.modal){state.modal=null;renderModal();}else{state.operation=null;state.measure=false;state.selected=null;state.selection=[];state.sheetSelected=false;render();}return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.modal='commands';renderModal();}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();act('save');}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();act(e.shiftKey?'redo':'undo');}}
let suppressSceneClick=false;
function bindWorkflowCanvas(){const el=document.getElementById('scene');if(!el||['parameters','export'].includes(state.mode))return;let moving=null;el.addEventListener('pointerdown',e=>{if(state.measure||state.operation||state.mode==='drawings'||state.mode==='sketch')return;const target=e.target.closest('[data-drag]'),svg=el.querySelector('svg');if(target&&svg){const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());moving={kind:'equipment',start:p,pos:{...state.room.laser},x:e.clientX,y:e.clientY};el.setPointerCapture(e.pointerId);}else if(state.view==='3d'&&!e.target.closest('[data-part]')){moving={kind:'orbit',x:e.clientX,y:e.clientY,yaw};el.setPointerCapture(e.pointerId);}});el.addEventListener('pointermove',e=>{if(!moving)return;moving.moved=Math.abs(e.clientX-moving.x)+Math.abs(e.clientY-moving.y)>4;if(!moving.moved)return;if(moving.kind==='equipment'){const svg=el.querySelector('svg'),p=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());state.room.laser.x=Math.max(285,Math.min(580,moving.pos.x+p.x-moving.start.x));state.room.laser.y=Math.max(190,Math.min(370,moving.pos.y+p.y-moving.start.y));}else yaw=moving.yaw+(e.clientX-moving.x)*.006;renderScene();});el.addEventListener('pointerup',()=>{if(moving?.moved){suppressSceneClick=true;if(moving.kind==='equipment')state.saved=false;}moving=null;});el.addEventListener('pointercancel',()=>moving=null);el.addEventListener('wheel',e=>{e.preventDefault();const n=Math.max(.65,Math.min(1.7,Number(el.dataset.zoom||1)+(e.deltaY<0?.035:-.035)));el.dataset.zoom=n;el.style.transform=`scale(${n})`;},{passive:false});}
function buildingStudyScene(){const s=.5,boxes=[];for(let i=0;i<8;i++)boxes.push(...boxFaces(-145,-115,i*90,290,230,9,'metal','Floor 0'+(i+1),s));boxes.push(...boxFaces(-25,-45,0,50,90,720,'dark','Core',s));boxes.sort((a,b)=>a.depth-b.depth);return svgOpen('Eight-level architectural study with drawing cut guides')+boxes.map(b=>b.markup).join('')+'</svg>';}
function workflowScene(){if(state.mode==='parameters')return parametersBoard();if(state.mode==='export')return exportsBoard();let out=state.project==='tower'&&state.mode!=='drawings'?buildingStudyScene():state.workspace==='room'&&state.project!=='makerspace'?isoScene():legacyScene();const overlays=[];if(state.workspace==='room'&&state.view==='plan'){for(const w of state.customWalls){const [a,b]=w.points;overlays.push(`<path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="#7c8b74" stroke-width="${w.thickness/10}" data-part="${esc(w.type)}"/><text x="${a.x+10}" y="${a.y+20}" class="tiny">${esc(w.type)}</text>`);}if(state.wallDraft.length){const a=state.wallDraft[0],b=state.wallDraft[1];overlays.push(`<circle cx="${a.x}" cy="${a.y}" r="5" fill="#bd6845"/>${b?`<path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="#bd6845" stroke-width="${state.typeThickness/10}" opacity=".6" stroke-dasharray="10 4"/>`:''}`);}state.buildingPlacements.forEach((p,i)=>{const x=280+i*80;overlays.push(p.kind==='stairs'?`<g data-part="${esc(p.type)}"><rect x="${x}" y="170" width="75" height="150" fill="#d8c7a6" stroke="#9c8c6b"/>${Array.from({length:12},(_,j)=>`<path d="M${x} ${180+j*11}h75" stroke="#9c8c6b"/>`).join('')}<path d="M${x+38} 305V180l-6 10m6-10 6 10" stroke="#b16b43" fill="none"/></g>`:`<g data-part="${esc(p.type)}"><rect x="${x}" y="230" width="70" height="30" fill="#c4d4c2" stroke="#799377"/><text class="tiny" x="${x}" y="225">${esc(p.type)}</text></g>`);});}
if(state.mode==='sketch'&&state.workspace==='sketch'&&state.sketchReferences.length)overlays.push(`<g stroke="#8870a4" fill="none" stroke-dasharray="5 3"><path d="M740 160v330M275 285h500"/><circle cx="740" cy="285" r="6" fill="#f7f3fc"/></g><text x="745" y="148" fill="#8870a4" font-size="11">Neighbor front · projected edge</text><text x="165" y="278" fill="#8870a4" font-size="11">Wall ∩ plane</text>`);
if(state.measure&&state.measurePicks.length===2)overlays.push(`<g><path d="M620 337v100M613 337h14M613 437h14" fill="none" stroke="#4d83a0" stroke-width="2"/><rect x="638" y="369" width="112" height="32" rx="5" fill="#edf6fb" stroke="#8ab0c4"/><text x="694" y="390" text-anchor="middle" fill="#3d7895" font-size="14">${state.project==='makerspace'?roomGap():state.project==='case'?'12.7':'24.0'} mm</text></g>`);
if(state.mode==='model'&&state.ribbon==='guides'){const h=state.guideHeight,y=state.project==='tower'?480-Math.min(340,h/60):360;overlays.push(`<path d="M300 ${y}l280-100 170 80-280 100Z" fill="#c59343" fill-opacity=".16" stroke="#b68a43" stroke-dasharray="7 4"/><path d="M750 ${y-20}h80" stroke="#b68a43"/><text x="830" y="${y-23}" class="label" text-anchor="end">${esc(state.guideKind)} +${h}</text><text x="830" y="${y-5}" class="tiny" text-anchor="end">3D guide → linked drawing page</text>`);}
if(state.railLinked||state.operation?.fromMcp)overlays.push(holeMarkers());
if(state.operation?.kind==='edge-treatment'||state.edgeApplied)overlays.push(`<g transform="translate(145 150)"><rect width="150" height="104" rx="6" class="annotation"/><text x="12" y="23" class="tiny">${state.edgeStyle.toUpperCase()} PROFILE</text><path d="M25 85V45${state.edgeStyle==='Fillet'?`Q25 38 33 38H120`:'L47 23H120'}" stroke="#b66b49" stroke-width="3" fill="none"/><text x="85" y="85" class="label">${state.edgeSize} mm</text></g>`);
return out.replace(/<\/svg>$/,overlays.join('')+'</svg>');}
function workflowDrawingScene(){const s=activeSheet(),portrait=s.paper.includes('portrait'),w=portrait?340:740,x=(1000-w)/2,y=100,h=440,mat=s.material||projects[state.project].materials[0],style=state.materialStyles[mat]||{hatch:'Diagonal',angle:45,spacing:4},spacing=Math.max(3,Number(style.spacing)*1.5);const pattern=style.hatch==='None'?'':style.hatch==='Solid'?'<rect width="16" height="16" fill="#8c9785"/>':`<path d="M0 0v${spacing}" stroke="#88967e" stroke-width="1"/>${style.hatch==='Cross hatch'?`<path d="M0 0h${spacing}" stroke="#88967e" stroke-width="1"/>`:style.hatch==='Wood grain'?`<path d="M2 0q4 4 1 ${spacing}" stroke="#9c885f" fill="none"/>`:''}`;let out=svgOpen('Linked drawing page '+s.number+' with material section hatching and title block')+`<defs><pattern id="drawing-hatch" width="${spacing}" height="${spacing}" patternUnits="userSpaceOnUse" patternTransform="rotate(${style.angle})">${pattern}</pattern></defs><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#fffef8" stroke="#d5d9cc"/><rect x="${x+15}" y="${y+16}" width="${w-30}" height="${h-32}" fill="none" stroke="#9ba28f" stroke-width=".6"/><text x="${x+32}" y="${y+39}" class="label">${esc(s.name.toUpperCase())}</text>`;
if(state.project==='makerspace'&&!s.guideId&&s.views.includes('Floor plan')){out+=roomScene().replace('<svg ','<svg x="145" y="142" width="560" height="300" ')+`<text class="tiny" x="710" y="210">25.4 m²</text><text class="tiny" x="710" y="233">Height ${state.wallHeight}</text>`;}else if(!s.views.length){out+=`<g data-action="add-view" style="cursor:pointer"><path d="M450 270h100M500 220v100" stroke="#c3cab8"/><text x="500" y="350" class="label" text-anchor="middle">Add a linked model view</text></g>`;}else{s.views.slice(0,4).forEach((v,i)=>{const viewScale=state.viewScales?.[s.number+':'+i]||s.scale;const xx=x+105+(i%2)*(w>500?340:130),yy=195+Math.floor(i/2)*150,scale=w>500?1:.48;out+=`<g transform="translate(${xx} ${yy}) scale(${scale})" data-sheet-view="${i}" style="cursor:pointer">${v.includes('Section')||v.includes('Detail')?`<path d="M0 0h215v18H18v76H0Z" fill="url(#drawing-hatch)" stroke="#5d7057"/><rect x="78" y="18" width="26" height="58" fill="url(#drawing-hatch)" stroke="#5d7057"/><text class="tiny" x="110" y="104" text-anchor="middle">${esc(mat)} · ${esc(style.hatch)}</text>`:v.includes('Isometric')||v.includes('Exploded')?`<path d="m20 10 130-25 45 30-130 26Z" fill="#e9edde" stroke="#64775c"/><path d="m20 10 45 31v40l-45-31Z M65 41l130-26v40L65 81Z" fill="#f5f5ea" stroke="#64775c"/>`:v.includes('Floor')||s.guideId?`<rect width="220" height="110" fill="none" stroke="#60765c" stroke-width="4"/><rect x="82" y="28" width="45" height="58" fill="url(#drawing-hatch)" stroke="#60765c"/>${[15,190].map(ax=>[15,85].map(ay=>`<rect x="${ax}" y="${ay}" width="12" height="12" fill="#75816f"/>`).join('')).join('')}`:`<rect width="215" height="100" rx="2" fill="none" stroke="#60765c" stroke-width="1.2"/><rect x="32" y="21" width="137" height="52" fill="none" stroke="#60765c"/>${[0,1,2].map(j=>`<circle cx="190" cy="${22+j*27}" r="5" fill="none" stroke="#60765c"/>`).join('')}${dimension(0,-18,215,-18,v==='Right'?(state.project==='table'?'800':'280'):(state.project==='table'?'1,600':'480'))}`}<text class="tiny" x="108" y="123" text-anchor="middle">${esc(v)} · ${viewScale}</text></g>`;});}
out+=`<text x="${x+32}" y="158" class="tiny">${esc((s.note||'').slice(0,portrait?40:100))}</text><path d="M${x+15} 485h${w-30}M${x+w*.55} 485v39M${x+w*.79} 485v39" fill="none" stroke="#8c9880" stroke-width=".7"/><text x="${x+26}" y="499" class="tiny">${esc(s.project).toUpperCase()}</text><text x="${x+26}" y="514" class="label">${esc(s.number)} · ${esc(s.name.slice(0,portrait?14:30))}</text><text x="${x+w*.57}" y="499" class="tiny">DRAWN BY</text><text x="${x+w*.57}" y="514" class="label">${esc(s.author)}</text><text x="${x+w*.81}" y="499" class="tiny">REV ${esc(s.revision)} · ${s.scale}</text><text x="${x+w*.81}" y="514" class="tiny">${state.activeSheet+1} / ${state.sheets.length}</text></svg>`;return out;}
