const legacyScene=scene,legacyOperationInspector=operationInspector,legacyProperties=properties,legacyRenderModal=renderModal,legacyAct=act,legacyHandleClick=handleClick,legacyHandleChange=handleChange,legacyHandleInput=handleInput,legacySymbolFields=symbolFields,legacyHoleMarkers=holeMarkers;
render=renderApplication;go=openProject;startOperation=beginTool;act=workflowAction;handleClick=workflowClick;handleChange=workflowChange;handleInput=workflowInput;bindCanvas=bindWorkflowCanvas;scene=workflowScene;drawingScene=workflowDrawingScene;
renderModal=function(){fieldScope='dialog';try{const markup=workflowModalMarkup();if(markup===null){legacyRenderModal();return;}overlays.innerHTML=markup;requestAnimationFrame(()=>overlays.querySelector('button,input,textarea,select')?.focus({preventScroll:true}));}finally{fieldScope='inspector';}};
symbolFields=function(id){const custom=state.customSymbols?.find(s=>s[0]===id);if(!custom)return legacySymbolFields(id);if(custom[2].startsWith('Static'))return '<p class="muted">Fixed definition · No instance parameters.</p>';return custom[4].map(name=>{const p=state.parameters.find(p=>p.name===name);return field(name,state['instance-'+name]??Number(p?.value||0),'instance-'+name,p?.unit||'mm');}).join('');};
holeMarkers=function(){if(state.project!=='case')return legacyHoleMarkers();return [0,1,2,3].map((n)=>{const p=projectPoint(-168,-65+n*Number(state.railPitch),125,.85);return `<g><ellipse cx="${p[0]}" cy="${p[1]}" rx="4" ry="5" fill="#fbf3df" stroke="#bc6844" stroke-width="1.7"/><text x="${p[0]+8}" y="${p[1]-3}" fill="#ad6949" font-size="9">H${n+1}</text></g>`;}).join('');};
commandResults=function(q){const found=new Map();for(const [group,tools]of Object.entries(ribbonTools))for(const [i,label,id]of tools)if(!found.has(id))found.set(id,[label,i,group.replace(':',' / ')]);return [...found].filter(([id,[label]])=>(label+' '+id).toLowerCase().includes(q.toLowerCase())).map(([id,[label,i,group]])=>`<button class="command-result" data-command="${id}">${icon(i)}${label}<small>${group}</small></button>`).join('')||'<p class="empty-state">No matching tools.</p>';};
